'use strict';
(function(){
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:w==='quina'?'Etymonline: https://www.etymonline.com/word/quinine':'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('quick','Quick comes from Old English cwic, “living or alive”; the sense “swift” developed from being lively, while the “quick” under a nail is the sensitive living flesh.',[C('quick.s1','快的；迅速的；短时间的','The technician made a quick repair to the pump so the clinic could reopen before noon.','技术员迅速修好了水泵，使诊所能在中午前重新开放。','The technician made a quick repair / so the clinic could reopen / before noon.','quick.s1 描述速度快或持续时间短的事物。','修理在短时间内完成，诊所得以及时开放。'),C('quick.s2','思维敏捷的；反应快的','A quick observer noticed that the quotation on the poster had omitted one word from the original speech.','一位反应敏捷的观察者发现海报上的引语漏掉了原演讲中的一个词。','A quick observer noticed / that the poster quotation / omitted a word.','quick.s2 指理解、观察或反应迅速敏锐。','观察者很快发现引文与原文不符。'),C('quick.s3','迅速地（口语）','“Come quick—the ferry is about to leave,” Mina called from the pier.','“快来，渡船就要开了！”米娜在码头上喊道。','“Come quick” / Mina called / as the ferry was about to leave.','quick.s3 可在非正式表达中作副词，替代 quickly。','口语命令 come quick 表示迅速过来。'),C('quick.s4','（指甲下的）活肉；痛处','The groomer trimmed the dog’s dark nails cautiously to avoid cutting the quick.','美容师小心修剪狗的黑色指甲，以免剪到里面的活肉。','The groomer trimmed the dark nails cautiously / to avoid cutting / the quick.','quick.s4 指指甲下敏感、容易疼痛的活肉，也可比喻痛处。','修剪时避开指甲内的敏感组织。')],M('The groomer cut the dog’s nail well above the quick, right through the sensitive flesh underneath.','The groomer cut the dog’s nail short of the quick to avoid the sensitive flesh underneath.','剪到活肉意味着切入指甲下的敏感组织，不是停在它上方。','meaning'),[q('What did the technician finish before noon?','a fast repair to the pump','a long quotation for a poster','a slow trim of a dog’s nails','技术员快速修理了水泵。',1,'context'),q('What does quick mean about the observer?','able to notice a missing word promptly','moving at the speed of a ferry','having sensitive flesh under a nail','观察者很快发现引文漏词，体现反应敏捷。',2,'context'),q('In “Come quick,” how is quick used?','as an informal adverb meaning quickly','as a noun for sensitive flesh','as an adjective describing a short repair','come quick 是口语副词用法，意思是快来。',3,'grammar'),q('What does the groomer avoid cutting?','the sensitive flesh under the nail','the poster’s original quotation','the ferry’s departure time','美容师要避开指甲下的活肉。',4,'meaning')]);
P('quickly','Quickly is formed from quick and the adverb suffix -ly; it means at a fast speed or without delay.',C('quickly.s1','快速地；不久','The dispatcher quickly rerouted the ambulance when roadwork blocked the bridge.','道路施工堵住桥梁后，调度员迅速为救护车改道。','The dispatcher quickly rerouted the ambulance / when roadwork / blocked the bridge.','quickly 修饰动作，表示速度快或没有耽搁。','道路受阻后调度员及时改道。'),M('The dispatcher quickly rerouted the ambulance by waiting several hours after learning the bridge was blocked.','The dispatcher quickly rerouted the ambulance as soon as the bridge was reported blocked.','得知桥梁封闭后等待数小时不是迅速处理。','meaning'),[q('What did the dispatcher reroute?','the ambulance','a dog’s nail','a quotation in a poster','调度员迅速为救护车改道。'),q('What does quickly mean?','at a fast speed or without delay','with a fixed share of a resource','in a calm, silent place','quickly 表示快速地或立即。',1,'meaning'),q('Which sentence uses quickly correctly?','The crew quickly shut the valve when the pipe began leaking.','The crew quickly arrived two days after the leak stopped.','The valve was a quickly object on the wall.','管道开始漏水时迅速关阀符合迅速行动的含义。',1,'grammar'),q('Which suffix forms quickly from quick?','-ly','-ness','-er','quick 加 -ly 构成副词 quickly。',1,'word-formation')]);
P('quicksand','Quicksand combines quick, in its older sense “living or shifting,” with sand; it is loose waterlogged sand that yields under weight and also a metaphor for a trap that worsens with struggle.',C('quicksand.s1','流沙；险境','The hiker stepped onto a patch of quicksand and stopped moving while the guide passed a branch to pull him out.','徒步者踩进一片流沙后停止挣扎，向导递来树枝把他拉了出来。','The hiker stepped onto quicksand / and stopped moving / while the guide passed a branch.','quicksand 指受压会流动、下陷的饱水沙地，也比喻越挣扎越难脱身的困境。','停下挣扎、借助外力帮助脱困。'),M('The guide warned that quicksand was a solid dry rock that could safely support the hiker’s full weight.','The guide warned that quicksand was saturated loose sand that could give way under the hiker’s weight.','流沙会在重量下下陷，不是坚硬干燥、稳固承重的岩石。','meaning'),[q('What did the hiker do after stepping onto quicksand?','stopped moving while the guide offered a branch','ran deeper into the loose sand','used the sand to repair the ferry','他踩入流沙后停止移动并接受向导帮助。'),q('What makes quicksand dangerous?','its waterlogged sand can yield under a person’s weight','it is a dry slab that never moves','it is a solid bridge that cannot collapse','饱水的松沙会在重量下流动下陷。',1,'meaning'),q('Which situation is metaphorical quicksand?','a debt problem that grows worse as someone borrows more to cover it','a dry beach that stays firm under every step','a short delay while a road is repaired','越借钱补债越陷越深的困境可比作 quicksand。',1,'context'),q('What older sense of quick appears in quicksand?','shifting or living','silent or calm','quoted or repeated','quick 的古义“活动、活的”与流动沙地的名称有关。',1,'word-formation')]);
P('quicksilver','Quicksilver is an old compound of quick and silver; quick once meant “living or lively,” describing the metal’s fluid motion, and the word is another name for mercury.',C('quicksilver.s1','水银；汞','The antique thermometer contained quicksilver, so the lab sealed it in a labeled container after the glass cracked.','旧温度计中含有水银，因此玻璃破裂后实验室将其封存在标记清楚的容器里。','The thermometer contained quicksilver / so the lab sealed it / after the glass cracked.','quicksilver 是液态金属汞的旧称。','温度计破裂后对水银采取了安全封存。'),M('The laboratory identified the liquid quicksilver as harmless drinking water and poured it into a glass.','The laboratory identified the liquid quicksilver as mercury and sealed it in a labeled container.','quicksilver 是汞，有毒性风险，不是可饮用的水。','meaning'),[q('What did the broken thermometer contain?','mercury','a bowl of fruit punch','a quotation from a speech','旧温度计中含有水银。'),q('What is quicksilver?','another name for the liquid metal mercury','a soft metal that is always a solid','a British slang word for one pound','quicksilver 是液态金属汞。',1,'meaning'),q('Why did the lab seal the quicksilver?','the glass thermometer had cracked','the metal had turned into a harmless drink','the ferry needed a quick repair','玻璃破裂后实验室封存了水银。',1,'context'),q('Why was mercury once called quicksilver?','quick once meant lively, referring to the metal’s fluid movement','it was the fastest way to buy silver','it was a silver quotation printed quickly','名称中的 quick 与汞的流动状态有关。',1,'word-formation')]);
P('quid','Quid is British informal slang for one pound sterling, attested in the 1680s; its origin is uncertain and may relate to Latin quid “what or something.”',C('quid.s1','一英镑（俚语）','The repair cost twenty quid, and the customer paid the mechanic in cash.','维修费是二十英镑，顾客用现金付给了机械师。','The repair cost twenty quid / and the customer paid / in cash.','quid 是英式口语中 pound 的非正式说法，通常不变复数。','二十 quid 表示二十英镑。'),M('The repair cost twenty quid, meaning the mechanic charged only one pound in total.','The repair cost twenty quid, meaning the mechanic charged twenty pounds.','twenty quid 指二十英镑，不是一英镑。','measurement'),[q('How much did the repair cost?','twenty pounds','one pound','twenty pence','维修费是二十英镑。'),q('What does quid mean in British informal speech?','one pound sterling','one hundredth of an Afghan afghani','a written quotation for a repair','quid 是英镑的口语说法。',1,'meaning'),q('Which phrase uses quid naturally?','The ticket was five quid.','The ticket was five quids sterling.','The ticket cost a quid of pounds.','five quid 是自然的口语表达。',1,'collocation'),q('What is known about quid’s origin?','it is uncertain, with a possible link to Latin quid','it certainly comes from Greek quill','it is a shortened form of quicksand','quid 的来源不确定，可能与拉丁语 quid 有关。',1,'word-formation')]);
P('quiescent','Quiescent comes from Latin quiescentem, the present participle of quiescere “to rest”; it describes something temporarily inactive or still.',C('quiescent.s1','静止的；休眠的','The volcano remained quiescent for decades, showing no new tremors or gas emissions.','这座火山数十年来一直处于休眠状态，没有新的震动或气体排放。','The volcano remained quiescent / for decades / with no new tremors or emissions.','quiescent 指暂时静止、休眠或缺少明显活动。','数十年没有震动或排放，说明火山暂时不活动。'),M('The volcano was quiescent while it erupted continuously and sent fresh ash over the town each hour.','The volcano was active while it erupted continuously and sent ash over the town.','持续喷发和不断排放火山灰不属于静止休眠状态。','meaning'),[q('What evidence showed the volcano was quiescent?','there were no new tremors or gas emissions','ash covered the town every hour','the mountain erupted without stopping','没有新的震动或排放表明火山处于休眠。'),q('What does quiescent mean?','temporarily still or inactive','moving rapidly from place to place','openly known to the public','quiescent 指暂时静止或不活跃。',1,'meaning'),q('Which machine is quiescent?','a pump switched off and showing no movement','a pump actively forcing water through a pipe','a motor vibrating while it runs','关闭且没有动作的泵处于静止状态。',1,'context'),q('Which Latin verb is behind quiescent?','quiescere, “to rest”','quotiens, “how many times”','quīnī, “five each”','quiescent 来自表示休息的拉丁语 quiescere。',1,'word-formation')]);
P('quietly','Quietly is quiet plus -ly; it means without much noise or in a calm, discreet manner.',C('quietly.s1','轻柔地；安静地','The nurse quietly closed the ward door so the sleeping patients would not wake.','护士轻轻关上病房门，以免吵醒熟睡的病人。','The nurse quietly closed the door / so the sleeping patients / would not wake.','quietly 修饰动作，可表示声音轻或方式平静、不张扬。','轻轻关门避免打扰病人。'),M('The nurse quietly closed the door by slamming it loudly and waking every patient in the ward.','The nurse quietly closed the door without making enough noise to wake the patients.','大声摔门会吵醒病人，不符合安静地关门。','meaning'),[q('Why did the nurse close the door quietly?','to avoid waking sleeping patients','to make the whole ward hear the door','to announce a public meeting','护士轻轻关门是为了不吵醒病人。'),q('What does quietly mean?','without much noise or in a calm way','at a fixed share of a resource','with a sharply strong smell','quietly 表示安静地或平静地。',1,'meaning'),q('Which action is done quietly?','placing a sleeping baby in the crib without a sound','dropping a metal pan on the floor','shouting across a crowded station','无声地把婴儿放进婴儿床是安静地做事。',1,'context'),q('Which suffix forms quietly?','-ly','-ity','-er','quiet 加 -ly 构成副词 quietly。',1,'word-formation')]);
P('quietude','Quietude entered English through French quiétude or Late Latin quietudo, from Latin quietus “calm or resting”; it means tranquility or repose.',C('quietude.s1','平静；寂静','At dawn, the garden’s quietude was broken only by the soft sound of water in the fountain.','黎明时，花园的宁静只被喷泉的轻柔水声打破。','The garden’s quietude / was broken only / by the soft fountain.','quietude 指环境、心境或处境的安宁与寂静。','周围寂静，只有喷泉发出轻声。'),M('The garden’s quietude was obvious because construction crews shouted and operated loud drills throughout the dawn.','The garden’s quietude was obvious because no traffic or construction disturbed the dawn.','清晨持续的喧闹施工与宁静相反。','meaning'),[q('What sound broke the garden’s quietude?','the soft fountain','a loud drill from a construction crew','a crowded public rally','只有喷泉的轻柔水声打破宁静。'),q('What does quietude mean?','tranquility or repose','a sudden racing contest','a small amount of money','quietude 指安宁、静谧。',1,'meaning'),q('Where might someone seek quietude?','a still garden at dawn','a crowded stadium during a race','a noisy workshop during repairs','黎明时安静的花园适合寻求宁静。',1,'context'),q('Which Latin word is related to quietude?','quietus, “calm or resting”','pungere, “to prick”','pupa, “doll”','quietude 源于表示安静、休息的拉丁词族。',1,'word-formation')]);
P('quill','Quill is recorded in English from about 1400 for a hollow feather shaft; it later named a writing pen made from a large feather and a porcupine spine.',C('quill.s1','羽根；羽毛笔；刺','The archivist displayed a goose quill beside the handwritten letter, while the naturalist showed a porcupine quill in another case.','档案员在手写信旁展示了一根鹅羽笔，自然学家则在另一展柜中展示了一根豪猪刺。','The archivist displayed a goose quill / beside the letter / while another case held a porcupine spine.','quill.s1 可指较大羽毛的硬中空羽轴、由此制成的羽毛笔或豪猪刺。','鹅羽笔与豪猪刺分别展示了词条中的两种物件。'),M('The archivist called a steel ballpoint pen a quill even though it had no feather shaft and used an ink cartridge.','The archivist called the cut feather shaft a quill pen.','钢珠笔没有羽毛硬轴，不能称为传统 quill。','meaning'),[q('What was displayed beside the handwritten letter?','a goose feather pen','a steel ballpoint with an ink cartridge','a quicksand sample','档案员展示了一支鹅羽笔。'),q('What can a quill be?','a feather shaft, feather pen, or porcupine spine','a device that sends radio waves','a small round root vegetable','quill 可指羽轴、羽毛笔或豪猪刺。',1,'meaning'),q('Which animal’s quill was in the naturalist’s case?','a porcupine','a rabbit','a raccoon','自然学家展示的是豪猪刺。',1,'context'),q('What is known about quill’s earlier history?','it was recorded for a hollow feather shaft, with a deeper origin uncertain','it is certainly a blend of quotation and -er','it comes directly from the Latin word for river','quill 早期指羽毛的中空羽轴，更深来源不确定。',1,'word-formation')]);
P('quilt','Quilt came through Anglo-French and Old French cuilte from Latin culcita, “mattress”; its verb sense means stitching through layers so a filling stays in place.',C('quilt.s1','缝制被子','Marta quilted the cotton top, soft filling, and backing together before binding the edges.','玛尔塔在包边前把棉布面、柔软填充层和底布缝在一起。','Marta quilted the top, filling, and backing / before binding / the edges.','quilt 作动词指缝合面布、填充层和底布，使各层固定。','三层材料被缝在一起后再包边。'),M('Marta quilted the blanket by separating its layers and leaving the filling loose between the top and backing.','Marta quilted the blanket by stitching its top, filling, and backing together.','缝被会把各层固定在一起，不是分离面布和底布。','meaning'),[q('What layers did Marta quilt together?','the top, filling, and backing','a quotation, a price, and a ratio','a quill, a spine, and a leaf','她把被子的面布、填充层和底布缝在一起。'),q('What does quilt mean as a verb?','stitch layers together to hold the filling in place','quote someone’s exact words','divide one number by another','quilt 作动词表示把被子的多层缝合固定。',1,'meaning'),q('Why was Marta quilting before binding the edges?','to secure the layers before finishing the edge','to keep the filling loose and removable','to calculate the quotient of the fabric','缝合固定各层后再包边是制作步骤。',1,'context'),q('Which Latin noun is in the history of quilt?','culcita, “mattress”','quietus, “resting”','quotiens, “how often”','quilt 经法语来自拉丁语 culcita，意为床垫。',1,'word-formation')]);
P('quilter','Quilter is formed from quilt and the agent suffix -er; it names someone who designs or sews quilts.',C('quilter.s1','缝被子的人','The quilter arranged the blue and cream fabric squares into a pattern before sewing the layers together.','缝被人先把蓝色和奶油色布块排成图案，再把各层缝在一起。','The quilter arranged fabric squares / before sewing / the layers together.','quilter 指设计或缝制被子的人。','布块拼图并缝合各层是缝被人的工作。'),M('The quilter designed the fabric pattern but never stitched or assembled any part of the quilt.','The quilter arranged the fabric and stitched the quilt’s layers together.','只设计布样但从未缝制的不是执行缝被工作的 quilter。','meaning'),[q('What did the quilter arrange before sewing?','blue and cream fabric squares','metal rails for a railway','numbers in a division problem','缝被人先排好蓝色和奶油色布块。'),q('Who is a quilter?','someone who designs or sews quilts','someone who calculates a quotient','someone who quotes a speech for a poster','quilter 指设计或缝制被子的人。',1,'meaning'),q('Which task would a quilter likely do?','stitching a top, filling, and backing together','measuring a train’s radio waves','collecting a quota of rainwater','把面布、填充层和底布缝在一起是缝被人的工作。',1,'context'),q('Which suffix identifies the worker in quilter?','-er','-ly','-ude','quilt 加 -er 构成表示从业者的 quilter。',1,'word-formation')]);
P('quina','Quina is the Spanish name for cinchona bark, ultimately from Quechua kina; the bark contains quinine and was historically used to treat malaria.',C('quina.s1','金鸡纳皮','The pharmacist labeled the dried quina bark as a historical source of quinine, not as a modern self-treatment.','药剂师把干燥的金鸡纳皮标注为奎宁的历史来源，而不是现代自行治疗用品。','The pharmacist labeled the bark / as a historical source of quinine / not as self-treatment.','quina 指金鸡纳树皮，是提取奎宁的原料。','标签说明树皮与奎宁的关系并提醒其历史用途。'),M('The pharmacist identified quina as the purified medicine itself rather than the bark from which quinine is obtained.','The pharmacist identified quina as cinchona bark from which quinine can be obtained.','quina 指金鸡纳树皮，不是提纯后的奎宁药物本身。','meaning'),[q('What did the pharmacist label?','dried cinchona bark','a dose of purified quinine tablets','a quill cut from a goose feather','药剂师标注的是金鸡纳树皮。'),q('What is quina?','cinchona bark from which quinine is obtained','a British word for one pound','a fixed share in a production limit','quina 指可提取奎宁的金鸡纳树皮。',1,'meaning'),q('Why did the label call the bark historical?','it was a source of quinine used against malaria','it was a modern self-treatment recommended without advice','it was a new type of quicksilver','金鸡纳皮是奎宁的历史来源，曾用于抗疟。',1,'context'),q('Which language supplied Spanish quina, according to the etymology?','Quechua','Old English','Latin','quina 经西班牙语与克丘亚语 kina 有关。',1,'word-formation')]);
P('quirk','Quirk appeared in English in the 1560s with an uncertain origin; it can mean an odd personal habit or an unexpected turn in a story, rule, or shape.',C('quirk.s1','怪癖；突变','One quirk of the old printer is that it reverses the first page after every long pause.','这台旧打印机有个怪毛病：每次长时间停顿后都会把第一页倒着打印。','One quirk of the old printer / is that it reverses the first page / after a long pause.','quirk 可指不寻常的习惯、特点或意外转折。','故障呈现出一种不寻常且反复出现的行为。'),M('The printer’s quirk was that it behaved exactly like every other model and never did anything unusual.','The printer’s quirk was that it reversed the first page after a long pause.','完全常规、从不出现特别行为不构成 quirk。','meaning'),[q('What unusual behavior does the old printer have?','it reverses the first page after a long pause','it quietly prints every page in the correct order','it quotes a speech from a poster','停顿后把第一页倒着打印是打印机的怪特点。'),q('What can a quirk describe?','an odd habit or an unexpected feature','a fixed payment of one pound','a smooth blanket sewn in layers','quirk 可指怪癖或意外特点。',1,'meaning'),q('Which is a personal quirk?','always arranging pencils by color before writing','arriving at the time written on the invitation','using punctuation correctly in a quotation','写作前总按颜色排列铅笔是个人怪癖。',1,'context'),q('What is known about quirk’s origin?','it is uncertain','it comes directly from Latin quiescere','it is a shortening of quicksilver','quirk 的词源至今不确定。',1,'word-formation')]);
P('quit','Quit came through Old French quitter from Latin quietare, “to make quiet or release”; it means stopping an activity, leaving a job or group, or going away from a place.',[C('quit.s1','停止；放弃（习惯或活动）','After the doctor explained the risks, Jo quit smoking and asked friends not to offer cigarettes.','医生解释风险后，乔戒了烟，并请朋友不要再递烟给她。','Jo quit smoking / after the doctor explained the risks / and asked for support.','quit.s1 指停止做某项活动或放弃某种习惯。','乔停止吸烟并寻求支持。'),C('quit.s2','辞职；退学；退出','The engineer quit her job at the factory when she accepted a research post at the university.','工程师接受大学研究职位后，辞去了工厂的工作。','The engineer quit her job / when she accepted / a university research post.','quit.s2 指主动离开工作、学校或组织。','接受新职位后她离开原工作。'),C('quit.s3','离开（某处）','The hikers quit the exposed ridge before the storm reached the mountain.','暴风雨抵达山区前，徒步者离开了无遮蔽的山脊。','The hikers quit the exposed ridge / before the storm / reached the mountain.','quit.s3 指离开一个地点。','徒步者在风暴到来前离开山脊。')],M('After accepting the university post, the engineer quit her job but continued reporting for every factory shift.','After accepting the university post, the engineer quit her job and stopped reporting for factory shifts.','辞职意味着离开原职位，而不是继续上每一班。','meaning'),[q('What habit did Jo stop?','smoking','working at the university','walking along an exposed ridge','乔戒掉了吸烟。',1,'context'),q('Why did the engineer quit her factory job?','she accepted a university research post','the storm reached the mountain','her friends offered her cigarettes','她接受大学研究职位后辞职。',2,'context'),q('What did the hikers do before the storm arrived?','left the exposed ridge','quit smoking','resigned from a factory job','他们在风暴到来前离开了山脊。',3,'context'),q('Which sentence uses quit to mean “stop an activity”?','He quit biting his nails after making a plan.','He quit the company to take another job.','She quit the ridge before the storm.','戒掉咬指甲的习惯体现停止一项活动。',1,'meaning')]);
P('quitter','Quitter is formed from quit and -er; it can mean someone who gives up before finishing or someone who avoids a responsibility or challenge.',[C('quitter.s1','半途而废者','The coach called no one a quitter for resting after the injury; the team focused on safe recovery.','受伤后休息时，教练没有把任何人称为半途而废者；球队专注于安全康复。','The coach called no one a quitter / for resting after injury / and focused on recovery.','quitter.s1 指开始后未完成便轻易放弃的人。','受伤后休息是安全康复，不等于轻率放弃。'),C('quitter.s2','逃避责任者','When the budget failed, the treasurer was not a quitter: she stayed to explain the accounts and fix the error.','预算出了问题时，财务主管没有逃避责任；她留下解释账目并纠正错误。','The treasurer was not a quitter / when the budget failed / because she stayed to fix it.','quitter.s2 可指遇到责任或挑战便逃避的人。','她留下处理预算问题，没有逃避责任。')],M('The treasurer was a quitter because she stayed late to explain the error and worked until the accounts were corrected.','The treasurer was not a quitter because she stayed to explain the error and correct the accounts.','留下来承担责任并解决问题，不能作为逃避责任的证据。','meaning'),[q('What did the coach say about the injured player?','resting safely did not make the player a quitter','the player had to race despite the injury','every injured person should leave the team','教练没有把安全休息的队员称为半途而废者。',1,'context'),q('How did the treasurer respond when the budget failed?','she stayed to explain the accounts and fix the error','she left before answering any questions','she blamed the quilter for the mistake','财务主管留下解释并纠错，没有逃避责任。',2,'context'),q('What is a quitter in the negative sense?','someone who abandons a task or responsibility too readily','someone who rests while recovering from an injury','someone who finishes a difficult assignment','轻易放弃或逃避责任的人可称为 quitter。',2,'meaning'),q('Which suffix turns quit into the person noun quitter?','-er','-ude','-ly','quit 加 -er 构成表示人的名词 quitter。',1,'word-formation')]);
P('quiver','Quiver has separate histories: the verb for trembling has an uncertain origin, while the arrow-case noun came through French forms, likely from a Germanic source. It means a slight shake or a case for arrows.',[C('quiver.s1','微微颤抖；抖动','Her voice began to quiver when she described the sudden explosion, though she continued answering questions.','她讲述突然爆炸时声音开始颤抖，但仍继续回答问题。','Her voice began to quiver / when she described the explosion / though she continued speaking.','quiver.s1 作动词指因寒冷、恐惧或激动而轻微快速颤抖。','讲述爆炸时声音出现颤抖。'),C('quiver.s2','轻微的颤抖','A quiver ran through the curtain when a gust of wind entered the open window.','一阵风从敞开的窗户吹进来，窗帘随之轻轻颤动。','A quiver ran through the curtain / when a gust / entered the room.','quiver.s2 作名词指短促轻微的抖动。','风使窗帘产生轻微摆动。'),C('quiver.s3','箭囊；箭袋','The archer returned each arrow to the quiver before stepping away from the practice range.','弓箭手离开练习场前把每支箭都放回箭袋。','The archer returned each arrow / to the quiver / before leaving the range.','quiver.s3 指携带箭的袋或套。','箭被放回专门装箭的袋中。')],M('The archer placed each arrow in the quiver, a case designed to carry arrows, and then called the case a trembling movement.','The archer placed each arrow in the quiver, the case designed to carry arrows.','装箭的袋是名词 quiver，不是表示颤抖的 movement。','meaning'),[q('What happened to the speaker’s voice?','it began to tremble','it became a case for arrows','it was quoted in the newspaper','讲述爆炸时她的声音开始颤抖。',1,'context'),q('What caused the curtain’s quiver?','a gust of wind through the open window','an archer putting arrows away','a quick repair to the pump','窗户吹进的风使窗帘轻轻颤动。',2,'context'),q('What did the archer put arrows into?','a quiver case','a quotation','a quicksand pit','弓箭手把箭放进箭袋。',3,'context'),q('Which sentence uses quiver as a noun for a small shake?','A quiver passed through the leaves in the breeze.','She quivered when the room grew cold.','He carried arrows in a leather quiver.','树叶间掠过轻微颤动，这里的 quiver 是抖动名词。',2,'grammar')]);
P('quiz','Quiz is an English word of uncertain origin first recorded in the late 18th century; it can mean a short test, to question someone, or a question-answer game.',[C('quiz.s1','小测验；小型考试','The teacher gave a short quiz on the chapter before students began the group discussion.','学生开始小组讨论前，老师对本章内容进行了一次小测验。','The teacher gave a short quiz / on the chapter / before group discussion.','quiz.s1 作名词指检查知识掌握情况的短测验。','小测验考查刚学完的章节。'),C('quiz.s2','盘问；连续提问','The reporter quizzed the contractor about the missed deadline and the missing safety inspection.','记者就错过的工期和缺失的安全检查连续询问承包商。','The reporter quizzed the contractor / about the delay / and the missing inspection.','quiz.s2 作动词可指连续提问以了解情况。','记者对承包商追问工期和检查问题。'),C('quiz.s3','问答比赛；智力竞赛','The radio quiz invited callers to answer history questions for a chance to win book vouchers.','电台问答比赛邀请听众来电回答历史问题，以赢取图书券。','The radio quiz invited callers / to answer history questions / for book vouchers.','quiz.s3 指由参与者回答问题进行的竞赛或节目。','参赛者通过回答问题争取奖品。')],M('The teacher gave a quiz by asking students to write a long research paper over the entire semester.','The teacher gave a short quiz by asking students a few questions about the chapter.','整学期研究论文不是短测验；quiz 是简短知识检查。','meaning'),[q('What did the teacher check before group discussion?','students’ knowledge of the chapter','the contractor’s safety license','the listeners’ book vouchers','老师在讨论前用小测验检查本章内容。',1,'context'),q('What did the reporter quiz the contractor about?','the missed deadline and absent inspection','the chapter’s spelling test','the radio station’s call-in prize','记者追问了承包商工期和安全检查。',2,'context'),q('What happened on the radio quiz?','callers answered history questions to win book vouchers','students wrote a semester-long research paper','the reporter issued a railway quota','听众通过回答历史问题参加问答比赛。',3,'context'),q('What is known about quiz’s origin?','it is uncertain, though the word is recorded in late-18th-century English','it derives certainly from Latin quiescere','it is a shortened form of quotation','quiz 的词源不确定，但英语中有18世纪末的记录。',1,'word-formation')]);
P('quota','Quota comes from Medieval Latin quota pars, “what share,” with quota from Latin quotus, “how many”; it means a fixed limit or an expected share of work.',[C('quota.s1','配额；限额；定量','The city set a daily water quota for each household during the drought.','旱灾期间，市政府为每户设定了每日用水限额。','The city set a daily water quota / for each household / during the drought.','quota.s1 指对可用或可生产数量设定的固定上限。','每户每日用水量有明确上限。'),C('quota.s2','定额；应完成的份额','Each recruiter had a monthly quota of six new apprentices to place with local workshops.','每名招聘人员每月须为本地工坊安排六名新学徒。','Each recruiter had a monthly quota / of six apprentices / to place with workshops.','quota.s2 指个人或团队预期应完成、贡献的份额。','每名招聘人员有明确月度目标。')],M('The household exceeded its quota while using less water than the fixed daily limit allowed.','The household exceeded its quota by using more water than the fixed daily limit allowed.','低于限额用水不是超过配额。','measurement'),[q('What did the city limit during the drought?','each household’s daily water use','the number of words in a quill','the hours a radio quiz could broadcast','市政府限制每户每日用水量。',1,'context'),q('What was each recruiter expected to place each month?','six new apprentices','six daily water meters','six quotations from the same speech','每名招聘人员每月要安排六名新学徒。',2,'context'),q('What does quota mean?','a fixed limit or an expected share','a short test or question game','a soft, calm state of mind','quota 可指固定限额或应完成的份额。',1,'meaning'),q('Which Latin phrase is behind quota?','quota pars, “what share”','quietus pars, “resting place”','quotiens pars, “division answer”','quota 来自表示“所占份额”的拉丁语短语。',1,'word-formation')]);
P('quotation','Quotation derives from Medieval Latin quotationem, from quotare “mark with numbers”; it can mean words quoted from a source or a statement of a price.',[C('quotation.s1','引用；引语','The report included a quotation from the mayor’s speech and gave the date and page number.','报告引用了市长演讲中的一句话，并标明日期和页码。','The report included a quotation / from the mayor’s speech / with a date and page number.','quotation.s1 指从书籍、演讲等来源摘录并引用的语句或段落。','出处信息帮助读者核查引语。'),C('quotation.s2','报价；估价','Before replacing the roof, the homeowners requested a written quotation from three contractors.','更换屋顶前，房主向三名承包商索取了书面报价。','The homeowners requested a written quotation / from three contractors / before replacing the roof.','quotation.s2 指对某项工作或商品给出的价格估算。','房主在施工前索取书面价格。')],M('The homeowners received a quotation for the roof repair that contained only a poem and no price estimate.','The homeowners received a quotation that stated the estimated price for repairing the roof.','维修报价应说明费用；只有诗句不构成价格估算。','meaning'),[q('What source did the report quote?','the mayor’s speech','the roof contractors’ price list only','the water quota notice','报告中的引语取自市长演讲。',1,'context'),q('Why did the homeowners request a written quotation?','to learn the estimated roof-repair price','to check the wording of the mayor’s speech','to calculate a division quotient','他们索取报价是为了了解屋顶维修估价。',2,'context'),q('Which meaning fits “a quotation from a novel”?','words copied from a source','a contractor’s price estimate','a fixed production limit','从小说中引用的内容是引语。',1,'meaning'),q('Which Latin verb is related to quotation?','quotare, “mark with numbers”','quiescere, “rest”','quillare, “write with a feather”','quotation 与拉丁语 quotare“标记编号”有关。',1,'word-formation')]);
P('quote','Quote is a back-formation from quotation, which came through Medieval Latin quotare, “mark with numbers”; as a verb it means repeat exact words or state a price, and as a noun it can be an excerpt or price.',[C('quote.s1','引用；引述原话','The student quoted the witness exactly and used brackets to mark a small clarification.','学生准确引用证人的原话，并用方括号标出一处小小的说明。','The student quoted the witness / exactly / and marked a clarification in brackets.','quote.s1 作动词表示准确重复他人说过或写过的话。','引述保留了证人的原话并标示编辑说明。'),C('quote.s2','报价；开价','The electrician quoted a fixed price for replacing the damaged breaker before starting work.','电工在开工前为更换损坏的断路器报出了固定价格。','The electrician quoted a fixed price / for replacing the breaker / before starting.','quote.s2 作动词表示告诉客户某项工作或商品的收费价格。','电工事先说明了维修费用。'),C('quote.s3','引文；引语','The article opened with a quote from the explorer’s diary about crossing the ice field.','文章以探险家日记中关于穿越冰原的一段引文开篇。','The article opened with a quote / from the explorer’s diary / about crossing the ice.','quote.s3 作名词指从他人言论或文字中摘录的部分。','文章引用了日记原文。'),C('quote.s4','报价；估价','We compared the contractor’s quote with two others before choosing a company to repair the roof.','我们把承包商的报价与另外两份比较后，才选择公司修屋顶。','We compared the contractor’s quote / with two others / before choosing a company.','quote.s4 作名词指商家给出的工作或商品价格。','三份维修估价被相互比较。')],M('The student quoted the witness exactly but replaced every original word with a different sentence.','The student quoted the witness exactly and marked any omitted words with an ellipsis.','准确引用要保留原话；完全换成别的句子不是原样引述。','meaning'),[q('How did the student handle the witness’s words?','quoted them exactly and marked a clarification','gave a fixed repair price','compared three roof estimates','学生准确引用了证人的话。',1,'context'),q('What did the electrician quote?','a fixed price for replacing the breaker','a passage from the explorer’s diary','a monthly water quota','电工报出了更换断路器的固定价格。',2,'context'),q('What opened the article about the expedition?','a passage from the explorer’s diary','a contractor’s roof estimate','a short test about punctuation','文章开头引用了探险家日记。',3,'context'),q('Which sentence uses quote as a noun meaning “price estimate”?','The builder sent a quote for repairing the roof.','The editor asked her to quote the witness.','The article began with a quote from a diary.','builder sent a quote 中 quote 指维修报价。',4,'meaning')]);
P('quotient','Quotient comes from Latin quotiens, “how many times”; it names the result of division and, by extension, a number used to express a level of ability.',[C('quotient.s1','（除法）商','The quotient is 12 because dividing 84 by 7 gives 12.','商是12，因为84除以7等于12。','The quotient is 12 / because 84 divided by 7 / gives 12.','quotient.s1 是除法运算中得到的结果。','84÷7的运算结果为12。'),C('quotient.s2','（能力）指数；商数','The report compared each team’s emotional quotient with its performance during high-pressure negotiations.','报告将各团队的情商指数与其在高压谈判中的表现作了比较。','The report compared emotional quotient / with team performance / during negotiations.','quotient.s2 可指表示某种能力水平的数值。','报告讨论了能力指数与表现之间的关系。')],M('In 84 divided by 7, the quotient is 91 because 84 and 7 are added.','In 84 divided by 7, the quotient is 12.','商是除法的结果；84÷7等于12，不是加法所得的91。','meaning'),[q('What is the quotient of 84 divided by 7?','12','91','7','84除以7的商是12。',1,'meaning'),q('What did the report compare with negotiation performance?','teams’ emotional quotient','the result of 84 divided by 7','the price of a repair','报告把团队的情商指数与谈判表现比较。',2,'context'),q('Which operation produces a quotient?','division','addition','quotation','quotient 是除法的结果。',1,'meaning'),q('What does quotient mean in the report?','a number expressing an ability level','a number obtained by adding two values','a passage copied from a diary','报告中的 quotient 指表示能力水平的数值。',2,'context')]);
P('rabbi','Rabbi came through Greek and Latin from Hebrew rabbi, “my master,” a respectful title for a Jewish teacher and religious leader.',C('rabbi.s1','拉比；犹太教教师','The rabbi explained the holiday readings to the congregation before the evening service.','晚间礼拜前，拉比向会众讲解了节日经文。','The rabbi explained the readings / to the congregation / before the service.','rabbi 指犹太教受按立的学者、教师或礼拜主持人。','拉比在礼拜前为会众讲解经文。'),M('The congregation asked the rabbi to lead the service, but he was introduced as the mosque’s imam.','The congregation asked the rabbi to lead the service at the synagogue.','rabbi 是犹太教教师或领袖；imam 是伊斯兰教职称。','word-choice'),[q('What did the rabbi explain to the congregation?','the holiday readings','the rules of a motor race','the price of a roof repair','拉比讲解了节日经文。'),q('Where would a rabbi ordinarily lead worship?','at a synagogue','at a racetrack','in a radio laboratory','犹太教拉比通常在犹太会堂主持礼拜。',1,'context'),q('Which title refers to a Jewish religious teacher?','rabbi','imam','racket','rabbi 指犹太教教师。',1,'meaning'),q('What does the older Hebrew element in rabbi mean?','my master','fast current','marked with numbers','rabbi 源自希伯来语 rabbi，字面含“我的主人”之意。',1,'word-formation')]);
P('rabbit','Rabbit is an English word of uncertain earlier origin; it names the small burrowing mammal and can also refer to its meat or fur.',[C('rabbit.s1','兔子','At dusk, a rabbit slipped through the hedge and disappeared into a shallow burrow.','黄昏时，一只兔子钻过树篱，消失在浅洞里。','A rabbit slipped through the hedge / and disappeared / into a shallow burrow.','rabbit.s1 指有长耳、短尾并常在洞穴中生活的小型哺乳动物。','兔子钻进洞穴躲藏。'),C('rabbit.s2','兔肉；兔毛','The menu listed rabbit stew, and the butcher kept the cleaned rabbit meat chilled until delivery.','菜单上有兔肉炖菜，肉店把处理好的兔肉冷藏到配送时。','The menu listed rabbit stew / and the butcher kept the meat chilled / until delivery.','rabbit.s2 可指兔肉或兔毛等取自兔子的材料。','菜单和肉店语境中 rabbit 指兔肉。')],M('The chef labeled a bowl of rabbit stew “carrot soup” even though it contained cooked rabbit meat.','The chef labeled the dish “rabbit stew” because it contained cooked rabbit meat.','菜肴含兔肉时不能准确标为纯胡萝卜汤。','meaning'),[q('Where did the rabbit disappear?','into a shallow burrow','onto the radio tower','under the tennis racket','兔子躲进了浅洞。',1,'context'),q('What did the butcher keep chilled?','cleaned rabbit meat','a living rabbit in its burrow','a feather used as a pen','肉店冷藏的是处理好的兔肉。',2,'context'),q('Which phrase uses rabbit to mean the animal?','A rabbit crossed the garden.','They served rabbit with herbs.','The coat was trimmed with rabbit fur.','第一句的 rabbit 指活兔。',1,'meaning'),q('Why is rabbit’s earlier word history stated cautiously?','its deeper origin is uncertain','it was certainly formed from radio and bit','it came directly from Latin for division','rabbit 的更早词源尚不确定。',1,'word-formation')]);
P('rabies','Rabies is from Latin rabies, “madness or rage”; it is a viral disease that attacks the brain and can spread through the saliva of an infected animal.',C('rabies.s1','狂犬病','After the bat bite, the clinic contacted public-health officials to assess the patient’s possible rabies exposure.','被蝙蝠咬伤后，诊所联系公共卫生部门评估患者可能接触狂犬病的情况。','After the bat bite / the clinic contacted officials / to assess possible rabies exposure.','rabies 是一种侵袭神经系统、通常经感染动物唾液传播的病毒性疾病。','诊所对咬伤后的狂犬病暴露风险进行评估。'),M('The traveler dismissed the bite as harmless because rabies is a bacterial skin rash that cannot affect the brain.','The traveler sought urgent medical advice because rabies is a serious viral disease that can affect the brain.','狂犬病是可侵袭脑部的病毒病，不是无害皮疹。','meaning'),[q('Whom did the clinic contact after the bat bite?','public-health officials','a racetrack announcer','a radio technician','诊所联系了公共卫生部门。'),q('How can rabies commonly spread?','through saliva from an infected animal bite','through a tennis racket string','through a quotation copied from a diary','感染动物的唾液可传播狂犬病。',1,'meaning'),q('What body system can rabies attack?','the brain and nervous system','the plant root system','the metal frame of a radio','狂犬病可侵袭脑部和神经系统。',1,'meaning'),q('Which part of speech is rabies in “possible rabies exposure”?','a noun naming a viral disease','an adjective meaning very angry','a verb meaning to race quickly','此处 rabies 是疾病名称名词。',1,'grammar')]);
P('raccoon','Raccoon entered English through an Algonquian language, probably Powhatan aroughcun; it names a nocturnal mammal with a ringed tail and nimble front paws.',C('raccoon.s1','浣熊','A raccoon opened the loose compost lid with its front paws and searched for scraps after dark.','一只浣熊用前爪掀开松动的堆肥桶盖，天黑后在里面寻找残渣。','A raccoon opened the lid / with its front paws / after dark.','raccoon 指夜行性哺乳动物，常见特征是环纹尾巴和灵巧前爪。','浣熊在夜间用前爪翻找食物。'),M('The wildlife guide identified the ring-tailed animal as a nocturnal raccoon, then described its pouch like a kangaroo’s.','The wildlife guide identified the ring-tailed animal as a raccoon with nimble front paws.','浣熊有灵巧前爪，但没有袋鼠那样的育儿袋。','meaning'),[q('What did the raccoon do with its front paws?','opened the compost lid','strung a tennis racket','measured radio waves','浣熊用前爪掀开了堆肥桶盖。'),q('When did it search for scraps?','after dark','at noon on the racetrack','during a morning service','浣熊夜间寻找食物。',1,'context'),q('Which feature is typical of a raccoon?','a ringed tail and nimble front paws','a long bill and webbed wings','a pouch for carrying its young','浣熊常有环纹尾巴和灵巧前爪。',1,'meaning'),q('Through which language family did raccoon enter English?','an Algonquian language','Medieval Latin for division','Old English for “living”','raccoon 经由阿尔冈昆语进入英语。',1,'word-formation')]);
P('race','Race has separate histories: the contest sense came through French from Italian razza, whose deeper origin is uncertain; the human-group sense is a sensitive social classification.',[C('race.s1','赛跑；速度竞赛','The two cyclists entered a race that followed the river road and finished near the old bridge.','两名骑行者参加了一场沿河岸公路举行的比赛，并在老桥附近抵达终点。','The cyclists entered a race / along the river road / and finished near the bridge.','race.s1 指较量速度、争取先到达终点的竞赛。','骑行者参加了沿河公路竞速。'),C('race.s2','种族；人种（宜慎用）','The historian discussed how race has been used to classify people, while stressing that such categories are socially constructed.','历史学家讨论了种族概念如何被用来划分人群，同时强调这类类别是社会建构的。','The historian discussed race / as a way people are classified / and stressed its social construction.','race.s2 是用于划分人群的社会概念，使用时应避免把它当作固定生物等级。','历史学家强调种族分类的社会性质。'),C('race.s3','急流；急奔的一段','A narrow race of water rushed through the mill channel after the storm raised the river.','暴雨抬高河水后，一股狭窄急流穿过了磨坊水道。','A narrow race of water rushed / through the mill channel / after the storm.','race.s3 可指水流湍急的河道或短促急奔。','暴雨后水流快速穿过水道。'),C('race.s4','参加比赛','They raced the restored car against a rival team along the closed coastal circuit.','他们驾驶修复好的汽车，在封闭的海岸赛道上与对手车队比赛。','They raced the restored car / against a rival team / on the coastal circuit.','race.s4 作动词表示参加速度竞赛。','修复车在赛道上与对手竞速。'),C('race.s5','疾驰；迅速移动','Mara’s heart raced when the alarm sounded in the empty station.','空荡的车站响起警报时，玛拉的心怦怦直跳。','Mara’s heart raced / when the alarm sounded / in the empty station.','race.s5 作动词可表示快速移动或急速跳动。','警报让她的心跳加速。')],M('The cycling team won the race by arriving at the finish after every other rider had already crossed it.','The cycling team won the race by crossing the finish line before the other riders.','最先抵达终点才可能赢得速度竞赛。','meaning'),[q('Where did the cyclists finish their race?','near the old bridge','inside the synagogue','at a laboratory radio tower','骑行比赛在老桥附近结束。',1,'context'),q('What did the historian stress about race as a human category?','it is socially constructed, not a fixed biological ranking','it is always a contest to reach a finish line','it means a fast current of water only','历史学家指出种族分类属于社会建构。',2,'context'),q('What rushed through the mill channel?','a narrow fast current of water','a quotation from a diary','a group of cyclists','磨坊水道中流过一股急流。',3,'context'),q('In “Mara’s heart raced,” what does raced describe?','her heart beating very fast','her entry in a cycling contest','a water channel at a mill','这里 raced 指心跳加速。',5,'meaning')]);
P('racetrack','Racetrack combines race and track; it names a prepared course for speed contests, especially horse or motor racing.',C('racetrack.s1','跑道；赛场','Workers resurfaced the racetrack before the annual motorcycle event so that the turns would be even and safe.','年度摩托车赛事前，工人重新铺设了赛道，使弯道平整安全。','Workers resurfaced the racetrack / before the event / to make its turns safe.','racetrack 指为速度比赛专门建造或铺设的赛道。','工人赛前修整了赛道弯道。'),M('The organizers built the racetrack as a quiet reading room with bookshelves instead of a racing course.','The organizers prepared the racetrack as a course for the motorcycle race.','racetrack 是竞速赛道，不是阅览室。','meaning'),[q('What did workers do before the motorcycle event?','resurfaced the course','replaced the radio antenna','repaired a synagogue roof','工人赛前重新铺设了赛道。'),q('Why did they make the turns even?','to improve safety for the race','to create a quotation display','to help a rabbit dig its burrow','平整弯道是为了比赛安全。',1,'context'),q('Which event is most likely held at a racetrack?','a horse race','a reading seminar','a rabies vaccination clinic','赛马通常在赛道举行。',1,'meaning'),q('Which words form racetrack?','race and track','radio and track','raccoon and rack','racetrack 由 race 和 track 组合而成。',1,'word-formation')]);
P('racial','Racial is formed from race with the adjective-forming suffix -ial; it means relating to racial groups or classifications.',C('racial.s1','种族的；族裔的','The museum revised its racial categories in the survey so visitors could describe their identities in their own terms.','博物馆修改了调查中的族裔分类，让参观者能用自己的方式描述身份。','The museum revised its racial categories / so visitors could describe / their identities in their own terms.','racial 表示与种族或族裔分类有关。','博物馆更新了调查中的分类方式。'),M('The report called a question racial even though it asked only how fast the cyclists completed their race.','The report called the identity categories racial because they concerned how people were grouped by race.','racial 修饰种族或族裔分类，不表示与赛跑速度有关。','word-choice'),[q('What did the museum revise?','racial categories in its survey','the surface of a racetrack','the spelling of a Latin quotation','博物馆修改了调查中的族裔分类。'),q('What does racial mean in “racial categories”?','relating to how people are grouped by race','relating to the speed of a contest','relating to radio waves','racial 表示与种族分类有关。',1,'meaning'),q('Which phrase correctly uses racial?','racial discrimination','racial racetrack','racial quotient of 84 divided by 7','racial discrimination 是正确搭配。',1,'collocation'),q('Which suffix appears in racial?','-ial','-less','-ment','racial 是 race 加形容词后缀 -ial 构成。',1,'word-formation')]);
P('racialism','Racialism combines racial with -ism and names a doctrine that ranks human groups by race and treats those rankings as natural.',C('racialism.s1','种族主义；种族等级论','The course analyzed racialism in colonial policy and showed how claims of innate superiority were used to justify unequal laws.','课程分析了殖民政策中的种族主义，说明所谓天生优越论如何被用来为不平等法律辩护。','The course analyzed racialism / in colonial policy / and examined its claims of superiority.','racialism 指按种族给人群排等级并将其视为自然秩序的思想。','课程讨论了这种等级论如何被用于辩护不平等。'),M('The lecture described racialism as the belief that all people are equal and should face no discrimination.','The lecture described racialism as a doctrine that ranks people by race and supports unequal treatment.','racialism 指种族等级论，而不是主张平等的立场。','meaning'),[q('What did the course analyze?','racialism in colonial policy','the shape of a radial road','the rules of a bicycle race','课程分析殖民政策中的种族主义。'),q('What does racialism claim?','that human groups can be ranked by race','that every race is a contest on a track','that race is only a river current','racialism 主张按种族给人群排等级。',1,'meaning'),q('Which policy would reflect racialism?','a law assigning unequal rights by racial group','a rule requiring helmets on a racetrack','a survey allowing people to describe identity freely','按种族群体分配不同权利的法律反映种族等级论。',1,'context'),q('What is the role of -ism in racialism?','it forms a noun for a doctrine or system','it marks a verb in the past tense','it makes the word mean a fast current','-ism 常构成表示思想体系或主义的名词。',1,'word-formation')]);
P('racing','Racing is formed from race with -ing; it names the sport of horse or motor contests and can also mark an ongoing race activity.',C('racing.s1','赛马；赛车运动','Racing attracts visitors to the coastal town every summer, especially when the classic cars arrive.','每年夏天，赛马和赛车运动都吸引游客来到海滨小镇，尤其是经典汽车抵达时。','Racing attracts visitors / to the coastal town / every summer.','racing.s1 指马匹或车辆之间的竞速运动。','赛车运动每年夏天吸引游客。'),M('The museum described racing as a quiet board game that never involves speed or competition.','The museum described racing as a sport in which horses or vehicles compete for speed.','racing 是速度竞赛运动，不是静态棋盘游戏。','meaning'),[q('When does racing attract visitors to the town?','every summer','only during winter storms','after the town closes its racetrack permanently','游客每年夏天因赛车运动来到小镇。'),q('What kind of event does racing involve?','a speed contest between horses or vehicles','a quotation contest between historians','a test of radio signal strength','racing 涉及马匹或车辆的速度比赛。',1,'meaning'),q('Which phrase is natural?','motor racing','motor racialism','motor quotient','motor racing 是自然搭配。',1,'collocation'),q('How is racing formed?','race plus the suffix -ing','radio plus the suffix -al','rabbit plus the suffix -ism','racing 由 race 加 -ing 构成。',1,'word-formation')]);
P('racism','Racism combines race and -ism; it refers to beliefs that rank races and to discrimination or unfair treatment based on race.',C('racism.s1','种族主义；种族歧视','The league adopted a reporting process so players could challenge racism in stadiums without being ignored.','联盟建立了举报程序，让球员能对体育场内的种族歧视提出异议而不被忽视。','The league adopted a reporting process / so players could challenge racism / in stadiums.','racism 指基于种族的等级观念、偏见或不公平对待。','联盟让球员能够举报体育场中的种族歧视。'),M('The club called its policy against racial abuse an example of racism because it protected players from discrimination.','The club called racial abuse racism and disciplined those responsible for it.','保护球员免受歧视的政策不是种族主义；种族辱骂才是。','meaning'),[q('What did the league create?','a process for reporting stadium racism','a new racetrack surface','a quotient for measuring radio signals','联盟建立了体育场种族歧视举报程序。'),q('What can racism include?','unfair treatment based on race','a contest to finish a track first','a fast current through a mill','基于种族的不公平对待属于 racism。',1,'meaning'),q('Which action addresses racism?','disciplining players who use racial abuse','ranking players by race for unequal rights','ignoring reports of discriminatory abuse','惩处种族辱骂行为有助于处理种族歧视。',1,'context'),q('What does -ism contribute to racism?','the idea of a doctrine or system','the meaning “small animal”','the meaning “fast current”','-ism 在 racism 中表示一种思想或制度。',1,'word-formation')]);
P('rack','Rack may come from Middle Dutch rek, “frame”; it names a support, an instrument of torture, or, as a verb, severe mental strain or effort.',[C('rack.s1','架子；搁架；行李架','The mechanic placed the spare tires on a wall rack to keep the workshop floor clear.','修理工把备用轮胎放在墙架上，以便腾出车间地面。','The mechanic placed the tires / on a wall rack / to clear the floor.','rack.s1 指用于支撑或存放物品的架子。','墙架用于存放轮胎。'),C('rack.s2','拉肢刑架；极大痛苦','The historian described the rack as a device once used to stretch a prisoner’s body during torture.','历史学家把 rack 描述为一种曾用于酷刑中拉伸囚犯身体的刑具。','The historian described the rack / as a device used in torture / to stretch a prisoner’s body.','rack.s2 可指历史上的拉肢刑具，也可比喻剧烈痛苦。','历史学家解释了刑具的用途。'),C('rack.s3','使痛苦；折磨','The unanswered question about the missing child racked the family with worry for days.','孩子失踪带来的悬而未决的问题让一家人连续数日备受焦虑折磨。','The unanswered question racked the family / with worry / for days.','rack.s3 作动词表示使人身心痛苦或焦虑。','家人因担忧而受折磨。'),C('rack.s4','绞尽脑汁；尽力回想','She racked her memory for the name of the small town where the train had stopped.','她绞尽脑汁回想火车停靠的那个小镇叫什么。','She racked her memory / for the name of the town / where the train had stopped.','rack.s4 常见于 rack one’s brains/memory，表示努力思考或回忆。','她努力回忆小镇的名字。')],M('The mechanic put the tires on the wall rack, then complained that the storage frame had forced him to stretch his body on a torture device.','The mechanic put the tires on the wall rack, a frame used to store equipment.','存放轮胎的墙架是支撑框架，不是刑具。','meaning'),[q('Where did the mechanic place the spare tires?','on a wall frame','on a racetrack','inside a radio receiver','修理工把轮胎放在墙架上。',1,'context'),q('What was the historical rack used for?','stretching a prisoner’s body during torture','holding spare tires in a workshop','measuring a team’s emotional quotient','历史上的 rack 是拉肢刑具。',2,'context'),q('What racked the family?','worry about the missing child','a sturdy shelf in the workshop','a fast bicycle race','孩子失踪的担忧折磨着家人。',3,'context'),q('What does “rack her memory” mean?','try very hard to remember','place her memory on a shelf','race away from a difficult question','rack her memory 表示努力回想。',4,'meaning')]);
P('racket','Racket for a stringed sports implement came through French raquette, ultimately from Arabic rāḥa “palm of the hand”; the noise and dishonest-scheme senses have distinct histories.',[C('racket.s1','球拍','He replaced a broken string on his tennis racket before joining the doubles match.','参加双打比赛前，他换掉了网球拍上断裂的球线。','He replaced a broken string / on his tennis racket / before the match.','racket.s1 指网球、羽毛球等运动中带网线的球拍。','球员更换了球拍上的断线。'),C('racket.s2','喧闹声；吵嚷','The children made such a racket in the hallway that the librarian closed the reading-room door.','孩子们在走廊里吵得很厉害，图书管理员只好关上阅览室的门。','The children made a racket / in the hallway / so the librarian closed the door.','racket.s2 指令人不快的巨大噪声。','走廊里的吵闹声影响了阅览室。'),C('racket.s3','敲诈勾当；骗局','Investigators uncovered a ticket racket that sold fake passes to people waiting outside the stadium.','调查人员揭露了一起售卖假通行证的票务骗局，受害者是在体育场外排队的人。','Investigators uncovered a ticket racket / selling fake passes / outside the stadium.','racket.s3 指通过欺诈或敲诈获利的非法勾当。','假票销售构成骗局。'),C('racket.s4','喧闹；吵闹（动词）','The teenagers racketed around the empty gym after the coach had locked the equipment room.','教练锁上器材室后，几个青少年在空体育馆里吵闹奔跑。','The teenagers racketed around / the empty gym / after practice.','racket.s4 作动词表示吵闹喧腾。','青少年在体育馆里制造喧闹。')],M('The neighbors complained about the racket, which was a soft whisper that nobody else could hear.','The neighbors complained about the racket, a loud and unpleasant noise from the hallway.','racket 的噪声义指响亮扰人的声音，不是无人能听见的轻声耳语。','meaning'),[q('What did the player repair before the doubles match?','a broken string on the tennis racket','a loose string on a radio antenna','a shelf used for storing tires','球员修理了网球拍上断裂的球线。',1,'context'),q('Why did the librarian close the door?','the hallway racket was disturbing readers','a ticket racket had sold fake passes','a tennis racket needed new strings','图书管理员因走廊太吵而关门。',2,'context'),q('What did investigators discover?','a scheme selling fake stadium passes','a new tennis tournament','a quiet reading-room rule','调查人员揭露了售卖假票的骗局。',3,'context'),q('Which meaning is used in “The teenagers racketed around the gym”?','they moved about noisily','they played tennis with a racket','they sold fraudulent tickets','racketed around 表示吵闹地活动。',4,'meaning')]);
P('racket sport','Racket sport is a transparent compound of racket and sport, naming an athletic game played with a racket, such as tennis or badminton.',C('racket sport.s1','球拍运动','The community center added badminton to its racket-sport program and loaned beginners lightweight rackets.','社区中心把羽毛球加入球拍运动项目，并向初学者借出轻型球拍。','The center added badminton / to its racket-sport program / and loaned rackets.','racket sport 指使用球拍进行的体育运动。','羽毛球被列入中心的球拍运动项目。'),M('The coach classified swimming as a racket sport even though the swimmers used no racket or ball.','The coach classified badminton as a racket sport because players strike a shuttlecock with rackets.','球拍运动需要使用球拍；游泳不属于此类项目。','word-choice'),[q('Which activity did the center add to its program?','badminton','radio monitoring','motor racing','社区中心加入了羽毛球项目。'),q('Why is badminton a racket sport?','players use rackets to strike a shuttlecock','it requires racers to circle a track','it measures a person’s numerical quotient','羽毛球运动员用球拍击打羽毛球。',1,'context'),q('Which pair are both racket sports?','tennis and badminton','swimming and hiking','racing and rabies','网球和羽毛球都是球拍运动。',1,'meaning'),q('What does racket sport literally combine?','a racket and an athletic sport','a radio and a track','a rabbit and a tennis string','racket sport 由 racket 和 sport 组合而成。',1,'word-formation')]);
P('radar','Radar is an acronym formed from radio detection and ranging; it uses reflected radio waves to locate objects and also appears figuratively in on someone’s radar.',[C('radar.s1','雷达','The harbor radar detected a small vessel behind the breakwater and sent its position to the coast guard.','港口雷达发现防波堤后方有一艘小船，并将其位置发送给海岸警卫队。','The harbor radar detected a vessel / behind the breakwater / and sent its position.','radar.s1 指利用无线电波探测物体位置的设备。','雷达探测到防波堤后方的小船。'),C('radar.s2','关注范围；监测视线（比喻）','The new safety concern was not on the committee’s radar until a worker reported repeated equipment failures.','直到一名工人报告设备反复故障，这项新的安全隐患才进入委员会的关注范围。','The concern was not on the committee’s radar / until a worker reported / repeated failures.','radar.s2 可比喻个人或机构正在关注、监测的范围。','设备故障报告让委员会注意到安全问题。')],M('The harbor radar located the vessel by bouncing sound from the waves, not by detecting radio signals.','The harbor radar located the vessel by detecting radio waves reflected from it.','radar 通过无线电波而不是声波探测物体。','meaning'),[q('What did the harbor radar detect?','a small vessel behind the breakwater','a missing quotation in a report','a tennis ball on the racetrack','港口雷达发现了一艘小船。'),q('When did the safety issue come onto the committee’s radar?','after a worker reported repeated failures','when the committee measured a division quotient','after a race finished at the harbor','工人报告反复故障后，委员会才关注此事。',2,'context'),q('How does radar locate many objects?','by detecting reflected radio waves','by weighing objects on a rack','by counting strings on a racket','雷达通过检测反射的无线电波定位物体。',1,'meaning'),q('What words form the acronym radar?','radio detection and ranging','rapid acoustic distance and racing','radioactive division and radial','radar 是 radio detection and ranging 的首字母缩略词。',1,'word-formation')]);
P('radial','Radial comes from Latin radius, “spoke or ray,” plus -al; it describes lines or structures extending outward from a center.',C('radial.s1','放射状的','The city plan added radial roads that run outward from the central square toward the suburbs.','城市规划增建了从中央广场向郊区延伸的放射状道路。','The plan added radial roads / from the central square / toward the suburbs.','radial 表示从中心向外沿直线或射线方向延伸。','道路从中央广场向外辐射。'),M('The engineer called a circular road radial because every point on it spiraled inward toward the center.','The engineer called the spokes radial because they extended outward from the wheel’s center.','放射状结构从中心向外延伸；仅仅呈圆形不等于 radial。','meaning'),[q('Where do the city’s radial roads begin?','at the central square','at the outer edge of each suburb','inside the harbor radar','放射状道路从中央广场出发。'),q('What does radial describe?','something extending outward from a center','something moving only in a closed circle','something that reflects radio waves','radial 指从中心向外延伸的结构。',1,'meaning'),q('Which object has a radial arrangement?','spokes extending from the hub of a wheel','parallel shelves along a wall','a single straight river channel','车轮轮辐从轮毂向外放射。',1,'context'),q('What was the older meaning of Latin radius?','spoke or ray','rabbit or fur','quote or price','radius 的拉丁语旧义包括“轮辐、光线”。',1,'word-formation')]);
P('radiant','Radiant comes from Latin radiare, “to shine or emit rays”; it describes bright light or a face that visibly shows joy.',[C('radiant.s1','发光的；容光焕发的','The solar panels faced the radiant morning sun, whose light reached the valley after the fog lifted.','雾散后，山谷迎来了明亮的晨光，太阳能板正对着太阳。','The panels faced the radiant sun / whose light reached the valley / after the fog lifted.','radiant.s1 可形容明亮发光，也可形容因喜悦而容光焕发。','雾散后阳光照亮了山谷。')],M('The photographer described the bride as radiant, although her face was hidden in complete darkness.','The photographer described the bride as radiant because her face glowed with happiness.','radiant 描写明亮或显露喜悦；完全被黑暗遮住时不合语境。','meaning'),[q('What happened after the fog lifted?','the sun’s light reached the valley','the valley was covered by a loud racket','the bicycle race began in darkness','雾散后阳光照到了山谷。',1,'context'),q('What can a radiant expression show?','visible happiness','deep confusion about a quotient','anger at a tennis racket','radiant 的神情可显出喜悦。',1,'meaning'),q('Which object is radiant in the context?','the morning sun','the fog itself','the closed reading-room door','语境中发光的是晨日。',1,'context'),q('Which root is linked to radiant?','Latin radiare, “to shine”','Greek rabies, “to race”','Old English rek, “a shelf”','radiant 与拉丁语 radiare“发光”有关。',1,'word-formation')]);
P('radiate','Radiate comes from Latin radiare, “to emit rays”; it can mean send out heat or light, show a quality, or spread outward from a center.',[C('radiate.s1','辐射；发射','The heater radiates warmth through the small studio even after the sun has set.','太阳落山后，暖气仍向小画室散发热量。','The heater radiates warmth / through the small studio / after sunset.','radiate.s1 表示发出光、热或其他能量。','暖气向室内散发热量。'),C('radiate.s2','流露；散发（情感、气质）','Although she was exhausted, the volunteer radiated calm confidence while guiding the frightened children.','尽管精疲力尽，志愿者在引导受惊的孩子时仍流露出沉着与自信。','The volunteer radiated confidence / while guiding the children / despite being exhausted.','radiate.s2 表示明显表现出某种情绪或特质。','志愿者表现出沉着自信。'),C('radiate.s3','从中心向四周散开','Narrow footpaths radiate from the visitor center toward four different sections of the park.','狭窄小径从游客中心向外通往公园的四个区域。','Footpaths radiate from the visitor center / toward four park sections.','radiate.s3 指线条或道路从中心向四周延伸。','小径从游客中心向外伸展。')],M('The heater radiated warmth by absorbing all heat and keeping the studio colder than before.','The heater radiated warmth by sending heat into the studio.','散发热量是向外传递能量，不是吸收热量并使室内更冷。','meaning'),[q('What did the heater radiate?','warmth through the studio','a social category from a report','a fast current through a mill','暖气向画室散发热量。',1,'context'),q('What quality did the volunteer radiate?','calm confidence','loud noise','a fixed price estimate','志愿者流露出沉着与自信。',2,'context'),q('From where did the park paths radiate?','the visitor center','the outer fence inward to one gate','the heater in the studio','小径从游客中心向外延伸。',3,'context'),q('Which meaning fits “radiate heat”?','send heat out','show a personality trait','spread in straight lines from a center','radiate heat 指向外散发热量。',1,'meaning')]);
P('radiating','Radiating is the present participle of radiate; as an adjective it describes energy or lines spreading outward from a source.',C('radiating.s1','辐射的；放射的','The radiating heat from the kiln made the workers step back before they opened its heavy door.','窑炉散发的热量让工人在打开沉重炉门前先退后了几步。','The radiating heat made the workers step back / before they opened / the kiln door.','radiating 描述从热源或中心向外发出的热、光或线条。','窑炉的热量向周围散发。'),M('The radiating heat from the kiln made the workers colder because it carried warmth inward and away from the room.','The radiating heat from the kiln warmed the nearby air and made the workers step back.','radiating heat 是向周围散发热量，不是把热量带走。','meaning'),[q('What made the workers step back?','heat coming from the kiln','a quiet reading-room rule','a quotation on the kiln door','窑炉散发的热量让工人后退。'),q('What does radiating describe here?','heat spreading outward from a source','a shelf holding tools','a contest on a motor track','radiating 描述从热源向外散发。',1,'meaning'),q('Which phrase is closest in meaning to radiating heat?','heat emitted from the kiln','heat absorbed by a cold wall','a narrow current of river water','radiating heat 是窑炉发出的热量。',1,'meaning'),q('Which verb is radiating derived from?','radiate','race','racket','radiating 是 radiate 的现在分词。',1,'word-formation')]);
P('radiation','Radiation is formed from radiate with the noun-forming suffix -ion; it is energy emitted as rays or particles.',C('radiation.s1','辐射；放射线','Technicians measured radiation around the sealed source and checked the readings before allowing anyone near the room.','技术人员测量了密封放射源周围的辐射，并在允许任何人靠近房间前检查读数。','Technicians measured radiation / around the sealed source / before allowing entry.','radiation 指以射线或粒子形式发出的能量。','人员进入前，技术员先测量周围辐射。'),M('The technician said radiation was a solid metal rack that blocked every particle and could be carried by hand.','The technician measured radiation as energy emitted from the sealed source.','radiation 是发出的能量，不是一个可手持的实体架子。','meaning'),[q('What did the technicians measure?','radiation around a sealed source','the length of a tennis racket','the emotional quotient of the staff','技术人员测量了密封放射源周围的辐射。'),q('What form can radiation take?','energy emitted as rays or particles','a frame used to hold tires','a short quotation from a report','radiation 可表现为射线或粒子形式的能量。',1,'meaning'),q('What did technicians do before allowing entry?','checked the radiation readings','started a bicycle race','removed every safety label','技术人员先检查辐射读数。',1,'context'),q('Which suffix helps form the noun radiation?','-ion','-less','-er','radiation 由 radiate 加名词后缀 -ion 构成。',1,'word-formation')]);
P('radiator','Radiator is formed from radiate with the agent or device suffix -or; it names a room heater or a vehicle part that cools an engine.',[C('radiator.s1','暖气片；暖气装置','The plumber bled the radiator to release trapped air, and the living room began to warm evenly.','管道工给暖气片放气后，客厅开始均匀升温。','The plumber bled the radiator / to release trapped air / and warm the room.','radiator.s1 指利用热水或蒸汽加热房间的设备。','放出暖气片中的空气后，房间升温。'),C('radiator.s2','（汽车）散热器','The mechanic flushed the car radiator before summer because old coolant had clogged its narrow channels.','夏天来临前，修理工冲洗了汽车散热器，因为旧冷却液堵住了细小通道。','The mechanic flushed the car radiator / before summer / to clear its channels.','radiator.s2 指帮助发动机散热的汽车部件。','修理工清理散热器以免发动机过热。')],M('The mechanic repaired the car radiator by sealing it shut so coolant could no longer flow through it.','The mechanic repaired the car radiator and restored coolant flow through its channels.','汽车散热器要让冷却液流过以带走发动机热量，不能把通道封死。','meaning'),[q('What did the plumber release from the room radiator?','trapped air','radio waves','a stream of river water','管道工从暖气片中放出了空气。',1,'context'),q('Why did the mechanic flush the car radiator?','old coolant had clogged its channels','the living room had become too warm','the tires needed a wall rack','修理工冲洗散热器是为清除堵塞。',2,'context'),q('Which radiator cools a vehicle engine?','the car radiator','the room radiator','the radio receiver','汽车散热器用于冷却发动机。',2,'meaning'),q('What does -or contribute to radiator?','the sense of a device that performs an action','the sense of a person who races','the meaning “without heat”','-or 可构成表示设备或施事者的名词。',1,'word-formation')]);
P('radical','Radical comes from Latin radicalis, “of a root,” from radix “root”; it can mean fundamental, politically far-reaching, root-related, or a person seeking major change.',[C('radical.s1','根本的；彻底的','The new schedule brought a radical change: the clinic now stays open through the night.','新日程带来了根本变化：诊所现在整夜开放。','The new schedule brought a radical change / because the clinic / stays open all night.','radical.s1 指触及事物根本性质的改变。','诊所从白天开放改为通宵开放。'),C('radical.s2','激进的；主张彻底改革的','The candidate proposed radical reforms to redistribute land and expand public services.','候选人提出激进改革，计划重新分配土地并扩大公共服务。','The candidate proposed radical reforms / to redistribute land / and expand services.','radical.s2 指主张社会或政治发生全面改变。','候选人提出大幅改革方案。'),C('radical.s3','根的；根源的（专业）','In the lesson, the teacher drew a radical sign before the number to indicate a square root.','课堂上，老师在数字前写下根号，表示平方根。','The teacher drew a radical sign / before the number / to indicate a square root.','radical.s3 在数学或语言学中可与根、词根有关。','根号标示了平方根。'),C('radical.s4','激进分子','The radical organized a peaceful march demanding major changes to the voting law.','这名激进分子组织和平游行，要求大幅修改选举法。','The radical organized a peaceful march / demanding major changes / to voting law.','radical.s4 指主张根本政治或社会变革的人。','游行者要求改革选举法。')],M('The council called the plan radical because it changed only the color of one small sign and left every basic policy untouched.','The council called the plan radical because it would fundamentally change the city’s housing policy.','只改一块小标牌不算根本改变；radical 指影响基础结构或政策。','meaning'),[q('What made the clinic’s schedule change radical?','it began staying open all night','it changed one sign’s color','it added a second radiator','诊所开始通宵营业，属于根本变化。',1,'context'),q('What did the candidate’s radical reforms propose?','redistributing land and expanding services','closing every racetrack','changing a single sign color','候选人提出重新分配土地并扩大公共服务。',2,'context'),q('What does radical mean before “sign” in a math lesson?','related to a root or square root','politically opposed to a policy','a person seeking social change','数学中的 radical sign 与根号有关。',3,'meaning'),q('Who is a radical in the final context?','a person demanding major voting-law changes','a person who repairs a car radiator','a person who measures radio waves','组织改革游行的人是此义的 radical。',4,'meaning')]);
P('radically','Radically is formed from radical and -ly; it means in a fundamental way or to a very great degree.',[C('radically.s1','根本地；彻底地','The merger radically changed the small company: it replaced its local supply chain with a global network.','合并从根本上改变了这家小公司：它用全球网络取代了本地供应链。','The merger radically changed the company / by replacing its local chain / with a global network.','radically.s1 表示以改变基本性质的方式。','合并重塑了公司的供应链结构。'),C('radically.s2','大幅度地；激烈地','Temperatures fell radically overnight, dropping from mild autumn weather to a hard frost.','气温一夜之间大幅下降，从温和的秋日天气降到严霜。','Temperatures fell radically / overnight / from mild weather to a hard frost.','radically.s2 表示程度极大或变化剧烈。','气温一夜骤降并出现严霜。')],M('The merger radically changed the company by leaving its ownership, supply chain, and policies exactly as they were.','The merger radically changed the company by replacing its local supply chain with a global network.','保持组织要素完全不变不构成根本改变。','meaning'),[q('What did the merger replace?','the local supply chain with a global network','a global network with one sign','a car radiator with a radio','合并用全球网络取代了本地供应链。',1,'context'),q('How far did temperatures fall?','from mild weather to a hard frost','only by a fraction of one degree','from a hard frost to summer heat','气温从温和降到严霜，变化幅度很大。',2,'context'),q('What part of speech is radically in “radically changed”?','an adverb modifying changed','a noun naming a reformer','an adjective describing a root','radically 是修饰动词 changed 的副词。',1,'grammar'),q('Which word is the base of radically?','radical','radium','racket','radically 由 radical 加 -ly 构成。',1,'word-formation')]);
P('radio','Radio is shortened from radiotelegraphy and related terms built on Latin radius, “ray”; it can name a receiver or broadcast system, communication, or sending a message by radio.',[C('radio.s1','收音机；无线电广播','She tuned the radio to the weather station and heard a warning about flooding along the river.','她把收音机调到气象台频率，听到沿河地区的洪水预警。','She tuned the radio / to the weather station / and heard a flood warning.','radio.s1 可指接收广播声音的设备或无线电广播系统。','收音机播出了洪水预警。'),C('radio.s2','无线电通讯','The mountain rescue team kept radio contact with the base while searching the snowy ridge.','山区救援队在雪岭搜寻时一直与基地保持无线电联系。','The team kept radio contact / with the base / while searching the ridge.','radio.s2 指利用无线电波进行的信息传递。','救援队通过无线电保持联系。'),C('radio.s3','用无线电发送；呼叫','The pilot radioed the control tower to report that a bird had struck the aircraft.','飞行员用无线电呼叫控制塔，报告飞机遭到鸟撞击。','The pilot radioed the tower / to report / a bird strike.','radio.s3 作动词表示通过无线电发送信息。','飞行员用无线电报告事故。')],M('The pilot radioed the tower by writing a note and leaving it on the runway for the control staff.','The pilot radioed the tower by transmitting a spoken message over the aircraft radio.','radio 作动词表示通过无线电发送，不是留下纸条。','meaning'),[q('What warning did she hear on the radio?','a flood warning','a report about a tennis match','a quotation from a diary','她从收音机里听到洪水预警。',1,'context'),q('How did the rescue team communicate with base?','by radio','by waving a tennis racket','by leaving a note on a racetrack','救援队与基地保持无线电联系。',2,'context'),q('What did the pilot radio to the tower?','a report of a bird strike','a weather forecast for the river','a request to repair a radiator','飞行员通过无线电报告鸟撞事故。',3,'context'),q('Which sentence uses radio as a verb?','The captain radioed the harbor about the damaged mast.','She listened to the radio at home.','The team lost radio contact in the tunnel.','radioed 在第一句中是通过无线电发送消息。',3,'grammar')]);
P('radioactive','Radioactive combines radio- with active and describes material whose unstable atomic nuclei emit radiation.',C('radioactive.s1','放射性的','The lab stored the radioactive sample behind shielding and tracked every transfer in a safety log.','实验室把放射性样品存放在屏蔽层后，并在安全日志中记录每次转移。','The lab stored the radioactive sample / behind shielding / and logged every transfer.','radioactive.s1 描述原子核不稳定、会释放辐射的物质。','样品被屏蔽存放并登记流转。'),M('The label called the sample radioactive because its stable atoms never emitted any radiation or particles.','The label called the sample radioactive because its unstable nuclei emitted radiation.','放射性物质的原子核不稳定并会释放辐射。','meaning'),[q('Where did the lab store the sample?','behind shielding','on an open desk beside the radio','inside the racetrack announcer’s booth','实验室把样品存放在屏蔽层后。'),q('Why was the sample labeled radioactive?','its unstable nuclei emitted radiation','it was a stable metal with no emissions','it had a ringed tail like a raccoon','不稳定原子核会释放辐射，因此样品具有放射性。',1,'meaning'),q('What did staff record in the safety log?','each transfer of the sample','the route of a cycling race','the words of a radio quotation','工作人员记录了样品每次转移。',1,'context'),q('Which material can be described as radioactive?','one whose unstable nuclei emit radiation','one that only reflects radio broadcasts','one that cannot contain any atoms','放射性物质的原子核会释放辐射。',1,'meaning')]);
P('radioactivity','Radioactivity is formed from radioactive and -ity; it names the spontaneous decay of unstable nuclei that releases radiation.',C('radioactivity.s1','放射性','Scientists measured the sample’s radioactivity over several days and recorded the declining count of emitted particles.','科学家连续数日测量样品的放射性，并记录释放粒子数量的下降。','Scientists measured radioactivity / over several days / and logged particle counts.','radioactivity 指不稳定原子核自发衰变并释放辐射的现象或性质。','研究人员连续测量粒子释放量。'),M('The report said the sample’s radioactivity was caused by stable nuclei that never changed or released energy.','The report linked the sample’s radioactivity to unstable nuclei that decayed and released energy.','放射性来自不稳定原子核的衰变，不是稳定原子核完全不变的结果。','meaning'),[q('What did scientists record during the study?','the declining count of emitted particles','the number of tennis strings','the speed of the river current','科学家记录了释放粒子数量的变化。'),q('What produces radioactivity?','spontaneous decay of unstable nuclei','stable nuclei that never change','a radio receiver’s speaker cone','不稳定原子核自发衰变会产生放射性。',1,'meaning'),q('How long did scientists measure the sample?','several days','one brief radio broadcast','until the racetrack opened','研究人员连续数日测量样品。',1,'context'),q('What suffix helps form radioactivity?','-ity','-less','-er','radioactivity 由 radioactive 加 -ity 构成。',1,'word-formation')]);
P('radiocarbon','Radiocarbon combines radio- and carbon; it usually refers to carbon-14, whose radioactive decay helps estimate the age of once-living material.',C('radiocarbon.s1','碳-14；放射性碳','Researchers measured radiocarbon in the wooden beam to estimate when the tree had been cut.','研究人员测量木梁中的碳-14，以估算树木被砍伐的年代。','Researchers measured radiocarbon / in the wooden beam / to estimate its age.','radiocarbon.s1 通常指放射性同位素碳-14，可用于测定曾经生物材料的年代。','木梁中的碳-14帮助估算树木年代。'),M('The archaeologist used radiocarbon dating on a recently made steel nail to learn when its iron ore was alive.','The archaeologist used radiocarbon dating on charcoal from the ancient hearth to estimate its age.','碳-14测年适用于曾经生物材料，不能用来测定钢铁矿石的“生长”年代。','context'),[q('What did researchers test for radiocarbon?','a wooden beam','a stainless-steel radio antenna','a stone racetrack marker','研究人员检测了木梁中的碳-14。'),q('What can radiocarbon help estimate?','the age of once-living material','the length of a circle’s radius','the speed of a tennis match','碳-14可用于估算曾经生物材料的年代。',1,'meaning'),q('Which sample is suitable for radiocarbon dating?','charcoal from an ancient fire','a newly made glass bottle','a piece of pure iron','古代木炭曾来自生物材料，可用碳-14测年。',1,'context'),q('Which element is named in radiocarbon?','carbon','radium','racket','radiocarbon 包含 carbon“碳”。',1,'word-formation')]);
P('radiological','Radiological is formed from radiology and -ical; it means relating to medical imaging or the use of radiation.',C('radiological.s1','放射学的；放射诊断的','A radiological examination revealed a small fracture that the first visual check had missed.','放射学检查发现了一处首次目视检查未能发现的小骨折。','A radiological examination revealed a fracture / that the first check / had missed.','radiological.s1 表示与放射学或辐射成像有关。','影像检查找到了先前漏诊的骨折。'),M('The clinic described the radiological scan as a handwritten interview with no imaging or radiation equipment.','The clinic described the radiological scan as an imaging examination performed with medical equipment.','放射学检查涉及医学成像，不是手写访谈。','meaning'),[q('What did the radiological examination reveal?','a small fracture','a missing radio quotation','a crack in a tennis racket','放射学检查发现了一处小骨折。'),q('What is radiological most closely related to?','medical imaging that uses radiation','a sport played with rackets','a doctrine that ranks people by race','radiological 与使用辐射的医学成像有关。',1,'meaning'),q('Why was the first check insufficient?','it had missed a small fracture later seen on imaging','it detected too much radioactivity in a food sample','it measured the wrong circle radius','首次检查漏掉了后来影像发现的小骨折。',1,'context'),q('Which noun is radiological based on?','radiology','radish','racing','radiological 由 radiology 加 -ical 构成。',1,'word-formation')]);
P('radiometric','Radiometric combines radio- with -metric, from Greek metron “measure”; it describes a measurement based on radiation or its decay.',C('radiometric.s1','放射性测量的','The geologists used a radiometric method to date the volcanic rock from the ratio of parent and daughter isotopes.','地质学家根据母体与子体同位素的比例，用放射性测量方法确定火山岩年代。','The geologists used a radiometric method / to date volcanic rock / from isotope ratios.','radiometric.s1 指依据辐射强度或放射性衰变进行测量的。','同位素比例用于估算岩石年代。'),M('The geologists called the test radiometric although it relied only on counting visible layers and measured no radiation or decay.','The geologists used a radiometric test based on radioactive decay and isotope ratios.','radiometric 测量以辐射或衰变为依据，不是单纯数可见地层。','meaning'),[q('What did the geologists date with the radiometric method?','volcanic rock','a tennis racket','a rabbit burrow','地质学家用该方法测定火山岩年代。'),q('What evidence did their method use?','the ratio of parent and daughter isotopes','the number of spokes on a radial wheel','the loudness of a radio broadcast','他们依据母体与子体同位素的比例。',1,'context'),q('What does radiometric describe?','measurement based on radiation or its decay','a device that only receives broadcasts','a political doctrine about race','radiometric 指依据辐射或其衰变进行测量。',1,'meaning'),q('What does metric contribute to radiometric?','the idea of measurement','the idea of a small root vegetable','the idea of a loud noise','-metric 与测量有关。',1,'word-formation')]);
P('radish','Radish came through Old English rædic from Latin radix, “root”; it names a small edible root vegetable and similar varieties.',[C('radish.s1','小萝卜；水萝卜','She sliced a crisp red radish over the salad, adding its peppery bite just before serving.','上菜前，她把脆嫩的红皮小萝卜切片放在沙拉上，增添了一丝辛辣味。','She sliced a red radish / over the salad / just before serving.','radish.s1 指红皮白瓤、常呈圆形的小型可食根菜。','切片的小萝卜为沙拉增添辛辣味。'),C('radish.s2','萝卜（泛指）','The farmer grew several radishes and related root vegetables in the cool soil beside the greenhouse.','农民在温室旁凉爽的土壤里种了几种萝卜及相近根菜。','The farmer grew radishes / and related root vegetables / beside the greenhouse.','radish.s2 可泛指类似的可食根菜。','农民种植了几种萝卜类作物。')],M('The cook grated a crisp red radish into the salad, then called the vegetable a sweet orange fruit from a tree.','The cook grated a crisp red radish into the salad as a peppery root vegetable.','radish 是根菜，不是树上生长的橙色甜水果。','meaning'),[q('What did she slice into the salad?','a crisp red radish','a piece of radioactive metal','a strip of old cleaning cloth','她把红皮小萝卜切片放进沙拉。',1,'context'),q('Where did the farmer grow the radishes?','in cool soil beside the greenhouse','on trees beside the racetrack','inside a radio receiver','农民在温室旁的凉爽土壤里种萝卜。',2,'context'),q('Which description fits a radish?','an edible root vegetable','a small nocturnal mammal','a device that cools a car engine','radish 是可食用的根菜。',1,'meaning'),q('What does the Latin source radix mean?','root','ray','rage','radish 的词源 radix 意为“根”。',1,'word-formation')]);
P('radium','Radium was coined from Latin radius, “ray,” for the radioactive element discovered by Marie and Pierre Curie.',C('radium.s1','镭','The museum kept the old radium paint sample sealed behind thick shielding and restricted access to the display.','博物馆把旧镭漆样品密封在厚屏蔽层后，并限制参观者接近展柜。','The museum kept the radium sample sealed / behind shielding / and restricted access.','radium.s1 指元素镭，一种具有危险放射性的金属元素。','含镭样品被密封并加以屏蔽。'),M('The curator handled the radium paint with bare hands because radium is a harmless stable gas.','The curator kept the radium paint sealed because radium is a hazardous radioactive element.','镭是危险的放射性元素，不是无害稳定气体。','meaning'),[q('How did the museum store the radium sample?','sealed behind thick shielding','open on a paper label','inside a tennis-racket case','博物馆把样品密封在厚屏蔽层后。'),q('What kind of element is radium?','a radioactive metal','a stable noble gas','a soft edible root','镭是一种放射性金属元素。',1,'meaning'),q('Who discovered radium?','Marie and Pierre Curie','the first radio announcers','the builders of a racetrack','镭由居里夫妇发现。',1,'context'),q('Which Latin word inspired the name radium?','radius, “ray”','radix, “root”','racket, “noise”','radium 的名称来自表示“光线”的 radius。',1,'word-formation')]);
P('radius','Radius comes from Latin radius, “spoke or ray”; in geometry it is the distance from a circle’s center to its edge.',C('radius.s1','半径','The surveyor measured the radius of the round plaza from its fountain at the center to the outer curb.','测量员从圆形广场中央的喷泉量到外缘路沿，测出了广场的半径。','The surveyor measured the radius / from the central fountain / to the outer curb.','radius.s1 是圆心到圆周任一点的距离。','测量从圆心延伸至圆形边缘。'),M('The student called the distance all the way across the circle through its center the radius, though it crossed both sides.','The student called the distance from the center to the circle’s edge the radius.','穿过圆心连接两侧的距离是直径；半径只从中心到一侧边缘。','meaning'),[q('Where did the surveyor begin measuring the plaza’s radius?','at the central fountain','at one curb and across to the opposite curb','at the racetrack entrance','测量从广场中央喷泉开始。',1,'context'),q('What is a circle’s radius?','the distance from its center to its edge','the distance across it through the center','the length of its outer boundary','半径是从圆心到圆周的距离。',1,'meaning'),q('How does a radius compare with a diameter?','it is half the diameter','it is twice the diameter','it is the same as the circumference','半径是直径的一半。',1,'meaning'),q('What did Latin radius originally refer to?','a spoke or ray','a root vegetable','an angry outburst','radius 的拉丁语旧义包括“轮辐、光线”。',1,'word-formation')]);
P('raffle','Raffle is an English word for a prize drawing; its earlier origin is uncertain, so no deeper root is asserted here.',C('raffle.s1','抽彩；抽签售物','The school held a raffle for a donated bicycle, and the winning ticket was drawn at the end of the fair.','学校为捐赠的自行车举行抽彩，并在集市结束时抽出了中奖号码。','The school held a raffle / for a donated bicycle / and drew the winning ticket.','raffle 指通过抽取彩票或号码来决定奖品归属的活动。','集市结束时抽出自行车的中奖票。'),M('The school promised every raffle ticket would win the bicycle, although it planned to draw only one winner.','The school explained that one raffle ticket would be drawn to win the bicycle.','抽彩通常从多张票中随机抽出获奖者，不能保证每张都中奖。','meaning'),[q('What prize did the school offer in its raffle?','a donated bicycle','a radio transmitter','a sack of radishes','抽彩奖品是一辆捐赠的自行车。'),q('When was the winning ticket drawn?','at the end of the fair','before any tickets were sold','during the bicycle race','中奖票在集市结束时抽出。',1,'context'),q('How is a raffle winner selected?','by drawing a ticket or number','by measuring a circle’s radius','by racing around a track','抽彩通过抽票或号码选出获奖者。',1,'meaning'),q('What is known about raffle’s deeper origin?','it is uncertain','it is certainly Latin for “ray”','it is a recent acronym for radio equipment','raffle 的更早词源尚不确定。',1,'word-formation')]);
P('raft','Raft may come from Old Norse raptr, “log”; it names a floating platform, a large number in a raft of, or the act of travelling or carrying goods by raft.',[C('raft.s1','木筏；救生筏','The hikers lashed branches together to build a raft and cross the slow stream before sunset.','徒步者把树枝绑在一起做成木筏，在日落前渡过缓慢的溪流。','The hikers built a raft / from lashed branches / to cross the stream.','raft.s1 指由木材或其他材料连成、能浮在水面的平台。','徒步者用木筏渡过溪流。'),C('raft.s2','大量（a raft of）','The committee received a raft of applications after it advertised the research grant online.','委员会在网上发布研究资助信息后，收到了大量申请。','The committee received a raft of applications / after advertising / the grant online.','raft.s2 常用于 a raft of，表示大量事物。','委员会收到许多申请。'),C('raft.s3','乘筏漂流；筏运','Local guides rafted tourists down the gentle section of river and unloaded them at the landing.','当地向导带游客乘筏漂过河流平缓河段，并在登陆点让他们上岸。','Local guides rafted tourists downstream / along the gentle section / to the landing.','raft.s3 作动词表示乘筏漂流或用筏运送。','游客乘筏漂到下游登陆点。')],M('The hikers built a raft from branches but expected it to sink immediately because a raft is a heavy object that cannot float.','The hikers built a raft from branches so it could float them across the stream.','raft 是能浮在水面的平台，制作目的就是漂浮和运载。','meaning'),[q('How did the hikers cross the stream?','on a raft made from branches','by driving a car radiator across it','by drawing a raffle ticket','徒步者乘树枝做的木筏过溪。',1,'context'),q('What did the committee receive a raft of?','applications for a grant','wooden beams for the river','radioactive samples','委员会收到大量资助申请。',2,'context'),q('What did the guides do for tourists?','raft them along a gentle river section','race them around a track','show them a radiological scan','向导带游客乘筏漂流。',3,'context'),q('Which expression means “a large number of”?','a raft of applications','a radius of applications','a rack of applications','a raft of 常表示“大量的”。',2,'meaning')]);
P('rag','Rag is recorded in Middle English for a worn or torn piece of cloth; the newspaper and teasing senses developed separately from the basic cloth sense.',[C('rag.s1','破布；抹布','She used an old rag to wipe oil from the workbench before replacing the machine’s filter.','她用一块旧抹布擦去工作台上的油，然后更换机器滤芯。','She used an old rag / to wipe oil / from the workbench.','rag.s1 指旧布片，常用来擦拭或清洁。','旧布被用来擦掉工作台上的油。'),C('rag.s2','破烂衣服（复数）','The rescue team brought blankets for people who had been left in rags after the flood.','洪水过后，救援队为衣衫褴褛的人们送来了毯子。','The rescue team brought blankets / for people left in rags / after the flood.','rag.s2 复数 rags 可指破旧、褴褛的衣服。','灾民的衣物破烂不堪。'),C('rag.s3','低俗小报（贬）','The editor refused to print the rumor, saying the paper would not become a rag that traded in gossip.','编辑拒绝刊登谣言，表示报纸不会沦为靠八卦牟利的低俗小报。','The editor refused to print a rumor / rather than turn the paper / into a gossip rag.','rag.s3 可贬称不受尊重、专登八卦的小报。','编辑不愿让报纸成为八卦小报。'),C('rag.s4','取笑；戏弄','His teammates ragged him about the bright socks, but he laughed and kept wearing them.','队友们拿他鲜艳的袜子打趣，但他笑着继续穿。','His teammates ragged him / about the bright socks / and he laughed.','rag.s4 作动词表示以粗率但常带玩笑意味的方式取笑某人。','队友们开玩笑取笑他的袜子。')],M('The mechanic wiped oil with a clean rag, then described the cloth as a brand-new silk uniform.','The mechanic wiped oil with an old rag, a worn piece of cloth used for cleaning.','用来擦油的旧布片是 rag，不是全新的丝质制服。','meaning'),[q('What did she use to wipe oil from the workbench?','an old rag','a tennis racket','a radiocarbon sample','她用旧抹布擦工作台上的油。',1,'context'),q('Who was described as being left in rags?','people after the flood','the editor’s newspaper','the radio announcer','洪水后衣衫褴褛的人们需要毯子。',2,'context'),q('Why did the editor reject the rumor?','to keep the paper from becoming a gossip rag','because the rag was needed to clean oil','because the paper was hosting a raffle','编辑不想让报纸沦为八卦小报。',3,'context'),q('How did the teammates rag him?','they teased him about his bright socks','they used his socks to wipe the workbench','they challenged him to a radiometric test','队友们拿他的鲜艳袜子打趣。',4,'meaning')]);
P('rage','Rage came through Old French rage from Latin rabies, “madness”; it can name intense anger or a sudden fashion, and it can describe angry action or forceful activity.',[C('rage.s1','盛怒；狂怒','A wave of rage swept over the driver when he saw the deliberate damage to his parked car.','看到停着的汽车被人故意损坏，司机顿时怒火中烧。','Rage swept over the driver / when he saw / the deliberate damage.','rage.s1 指强烈而难以控制的愤怒。','汽车遭故意损坏让司机暴怒。'),C('rage.s2','风靡一时的事物','For a few months, brightly colored running shoes were all the rage among students at the university.','有几个月，鲜艳的跑鞋在大学生中风靡一时。','Bright running shoes were all the rage / among students / for a few months.','rage.s2 常见于 all the rage，表示当时流行的事物。','鲜艳跑鞋一度成为校园潮流。'),C('rage.s3','发怒；怒斥','The customer raged at the clerk over a billing mistake, although the clerk had offered to correct it.','顾客因账单错误冲柜员大发脾气，尽管柜员已经提出更正。','The customer raged at the clerk / over a billing mistake / despite the offer to correct it.','rage.s3 作动词表示因愤怒而激烈说话或行动。','顾客因账单错误怒斥柜员。'),C('rage.s4','（风暴、战斗等）猛烈进行','The wildfire raged through the dry valley overnight, forcing residents to leave their homes.','野火一夜之间猛烈席卷干燥的山谷，迫使居民离开家园。','The wildfire raged through the valley / overnight / forcing residents to leave.','rage.s4 可描述风暴、冲突或火势猛烈持续。','野火猛烈蔓延并迫使居民撤离。')],M('The customer raged at the clerk by calmly thanking her and quietly accepting the corrected bill.','The customer raged at the clerk by shouting angrily about the billing mistake.','平静道谢并接受更正不是大发脾气。','meaning'),[q('What triggered the driver’s rage?','deliberate damage to his car','a popular pair of running shoes','a radio warning about flooding','司机看到汽车被故意损坏后暴怒。',1,'context'),q('What was all the rage among students?','brightly colored running shoes','old cleaning rags','radiometric rock tests','鲜艳跑鞋一度风靡校园。',2,'context'),q('How did the customer rage at the clerk?','by angrily shouting over a billing mistake','by silently repairing a radiator','by drawing a raffle ticket','顾客因账单错误怒斥柜员。',3,'context'),q('What happened when the wildfire raged?','it spread forcefully through the valley','it became a briefly fashionable shoe','it stopped before reaching dry ground','野火猛烈席卷山谷。',4,'context')]);
P('ragged','Ragged is formed from rag and -ed; it describes torn, shabby clothing or an uneven, rough edge or surface.',[C('ragged.s1','衣衫褴褛的','The ragged traveler accepted a clean coat from the shelter before continuing toward the station.','衣衫褴褛的旅人从收容所接过一件干净外套，随后继续前往车站。','The ragged traveler accepted a coat / from the shelter / before leaving.','ragged.s1 描写衣物破旧、撕裂或穿着褴褛。','收容所为衣衫褴褛的旅人提供外套。'),C('ragged.s2','参差不齐的；粗糙的','A ragged line of stones marked the edge of the old field, with gaps where rain had washed soil away.','一排参差不齐的石头标出了旧田地边界，雨水冲走泥土的地方留下了缺口。','A ragged line of stones / marked the field edge / with gaps from erosion.','ragged.s2 可形容边缘参差、表面粗糙或不规则。','石头排列不齐且有缺口。')],M('The tailor called the jacket ragged even though it was new, perfectly smooth, and had no tears or uneven edges.','The tailor called the jacket ragged because its sleeve was torn and its hem was frayed.','ragged 描写破损衣物或不平整边缘；完整平滑的新衣不符合该义。','meaning'),[q('What did the shelter give the traveler?','a clean coat','a piece of radium','a stringed racket','收容所给旅人一件干净外套。',1,'context'),q('What marked the edge of the field?','a ragged line of stones','a smooth circle with a measured radius','a radio station’s schedule','田地边界由参差石头标出。',2,'context'),q('Which item is ragged in the clothing sense?','a torn jacket with a frayed hem','a new smooth coat','a precisely measured radial road','破裂并磨损的夹克是 ragged。',1,'meaning'),q('Which item is ragged in the edge sense?','an uneven line with gaps','a perfectly straight painted line','a circle with a fixed radius','有缺口且不规则的线条是 ragged。',1,'meaning')]);
P('ragtime','Ragtime is an American musical term from the 1890s, often linked to its “ragged” syncopated rhythm; it names piano music with an offbeat melody over a steady beat.',C('ragtime.s1','散拍乐','The pianist played ragtime with a steady left-hand march and a lively, syncopated melody in the right hand.','钢琴家演奏散拍乐，左手保持稳定的进行节奏，右手弹出活泼的切分旋律。','The pianist played ragtime / with a steady left-hand beat / and a syncopated right-hand melody.','ragtime.s1 是约1900年前后流行的一种钢琴音乐，旋律常以切分音错开稳定节拍。','左手稳定节拍与右手切分旋律形成对比。'),M('The pianist called the piece ragtime even though both hands played only the same unaccented notes on every beat.','The pianist played ragtime with a steady beat and a syncopated melody.','散拍乐的重要特征是旋律相对稳定节拍产生切分错位。','meaning'),[q('What did the pianist’s left hand provide?','a steady march-like beat','a series of radio signals','a ragged line of stones','左手保持稳定的进行节奏。'),q('How did the right-hand melody sound?','lively and syncopated','silent and without rhythm','like a spoken quotation','右手旋律带有切分节奏。',1,'context'),q('What is ragtime?','piano music with syncopation over a steady beat','a folk dance performed only on a raft','a radio method for measuring radiation','ragtime 是稳定节拍上带切分旋律的钢琴音乐。',1,'meaning'),q('Why is the name sometimes associated with “ragged” rhythm?','the melody accents fall unevenly against the steady beat','the performers wore torn clothes','the piano keys were made of cloth','名称常被联系到旋律相对节拍的错落切分。',1,'word-formation')]);
P('raid','Raid is related to Scots raide, “a riding,” from an Old English word for riding; it can be a sudden attack or search, and as a verb it can mean attack or take something quickly.',[C('raid.s1','突袭；袭击','At dawn, the soldiers launched a raid on the fort and withdrew before the defenders regrouped.','黎明时，士兵突袭了堡垒，并在守军重新集结前撤离。','At dawn, the soldiers launched a raid / on the fort / and withdrew quickly.','raid.s1 指突然发动的短促攻击。','士兵黎明突袭并迅速撤离。'),C('raid.s2','突击搜查；突击缉捕','Police carried out a raid on the warehouse after a judge approved a warrant to search for stolen equipment.','法官批准搜查令后，警方突击搜查了仓库，寻找被盗设备。','Police carried out a raid / on the warehouse / under an approved warrant.','raid.s2 指警方等突然进入场所搜查或缉捕。','警方依搜查令突击检查仓库。'),C('raid.s3','突袭；抢劫；把……吃光（口语）','The children raided the refrigerator for fruit after the long bicycle ride.','长途骑行后，孩子们翻冰箱找水果吃。','The children raided the refrigerator / for fruit / after the ride.','raid.s3 作动词可指突袭、抢取，也可口语表示迅速搜取食物等。','孩子们骑行后翻找冰箱里的水果。')],M('The police announced a raid but waited for the warehouse owner to invite them in and show every room voluntarily.','The police carried out a raid under a warrant and searched the warehouse without advance notice.','突击搜查具有突然性，不是提前邀请房主带路参观。','meaning'),[q('When did the soldiers raid the fort?','at dawn','after a long bicycle ride','during a radio broadcast','士兵在黎明突袭堡垒。',1,'context'),q('Why did police enter the warehouse?','to search for stolen equipment under a warrant','to prepare a ragtime concert','to measure a circle’s radius','警方依搜查令进入仓库寻找被盗设备。',2,'context'),q('What did the children raid?','the refrigerator for fruit','the fort with weapons','the police station for warrants','孩子们翻冰箱找水果。',3,'context'),q('What is common to the noun sense of raid?','a sudden short attack or search','a slow invitation to tour a building','a device that cools an engine','raid 作名词指突然的攻击或搜查。',1,'meaning')]);
P('raider','Raider is formed from raid and the agent suffix -er; it names a person or group that makes a sudden attack or robbery.',C('raider.s1','袭击者；突袭部队','The museum guard spotted a raider trying to break through the side entrance after closing time.','博物馆保安发现一名袭击者试图在闭馆后闯入侧门。','The guard spotted a raider / trying to break through / the side entrance.','raider.s1 指突然发动攻击或抢劫的人或团体。','保安发现有人试图夜间闯入博物馆。'),M('The museum called the guard a raider even though he was protecting the building from a person trying to break in.','The museum called the intruder a raider because he tried to force entry after closing time.','保护建筑的保安不是袭击者；试图闯入者才符合此义。','word-choice'),[q('Where did the raider try to enter?','through the museum’s side entrance','through the car radiator','through the radio broadcast','袭击者试图从博物馆侧门闯入。'),q('When did the guard spot the raider?','after closing time','during the morning raffle','at the end of the bicycle race','保安在闭馆后发现闯入者。',1,'context'),q('Who is a raider?','a person who makes a sudden attack or robbery','a worker who repairs room heaters','a player holding a tennis racket','raider 指发动突然袭击或抢劫的人。',1,'meaning'),q('Which suffix forms raider from raid?','-er','-ly','-ity','raid 加施事者后缀 -er 构成 raider。',1,'word-formation')]);
P('rail','Rail comes through Old French reille, “bar”; it can mean a barrier, a train track or travel by train, and the verb can mean complain angrily.',[C('rail.s1','栏杆；扶手；横杆','She held the rail as she climbed the wet stairs to the station platform.','她握住扶手，走上通往车站站台的湿滑楼梯。','She held the rail / as she climbed the wet stairs / to the platform.','rail.s1 指固定在一处、用于支撑或防护的横杆。','乘客扶着栏杆上楼梯。'),C('rail.s2','铁轨；铁路运输','The freight train carried grain along the rail line from the inland depot to the harbor.','货运列车沿铁路线把谷物从内陆仓库运到港口。','The train carried grain / along the rail line / to the harbor.','rail.s2 可指列车行驶的铁轨，也可指铁路运输。','列车通过铁路把谷物运到港口。'),C('rail.s3','怒斥；抱怨','Residents railed against the late-night construction noise at the public meeting.','居民在公众会议上怒斥深夜施工噪声。','Residents railed against the noise / at the public meeting.','rail.s3 作动词表示愤怒地抱怨或谴责。','居民公开批评施工噪声。')],M('The passenger held the rail by stepping onto it as if it were a train track, then complained that it supported her hand.','The passenger held the rail beside the stairs for support while climbing.','楼梯旁的 rail 是供手扶的栏杆，不是供列车行驶的铁轨。','meaning'),[q('What did the passenger hold while climbing the stairs?','the safety rail','a freight train','a raincoat sleeve','乘客上楼时扶住了栏杆。',1,'context'),q('How did the train carry grain to the harbor?','along the rail line','by railing against the noise','on a balcony handrail','货运列车沿铁路线运送谷物。',2,'context'),q('What did residents do at the public meeting?','railed against late-night construction noise','repaired the railway tracks','held a rail to climb stairs','居民在会上怒斥深夜施工噪声。',3,'context'),q('Which phrase means “travel by train”?','go by rail','hold the rail','rail against a decision','go by rail 表示乘火车出行。',2,'meaning')]);
P('railhead','Railhead combines rail and head; it names the end of a railway line where passengers or freight can transfer to other transport.',C('railhead.s1','铁路线终点；铁路装卸站','The army moved supplies from the remote railhead to the mountain camp by truck because no track continued beyond it.','铁路不再向前延伸后，军方用卡车把物资从偏远铁路终点运到山地营地。','The army moved supplies / from the remote railhead / by truck.','railhead.s1 指铁路线路终点或供货物转运的铁路站点。','物资从铁路终点改由卡车接运。'),M('The freight team called the harbor a railhead even though no railway reached it and all cargo arrived by boat.','The freight team unloaded the supplies at the railhead, where the railway ended and trucks took over.','铁路终点需要铁路线到达；完全没有铁路的港口不符合 railhead。','meaning'),[q('How did supplies leave the railhead?','by truck','by a train continuing along a track that did not exist','by a raft through the harbor','卡车从铁路终点接运物资。'),q('Why was that point called the railhead?','the railway ended there and cargo transferred to trucks','it was the beginning of a rainbow','it was a rail used to hold a coat','铁路在此终止，货物转由卡车运输。',1,'context'),q('What is a railhead?','the end of a railway line used for transfer','a handrail beside a flight of stairs','a rainwater collection tank','railhead 是铁路终点或转运点。',1,'meaning'),q('Which words form railhead?','rail and head','rain and head','rally and track','railhead 由 rail 和 head 组合而成。',1,'word-formation')]);
P('railing','Railing is formed from rail and -ing; it names a fence-like row of rails, especially one beside stairs, a balcony or a bridge.',C('railing.s1','栏杆；扶手','The child leaned against the balcony railing while her father checked that every bolt was secure.','孩子靠着阳台栏杆，父亲检查每一颗螺栓是否牢固。','The child leaned against the railing / while her father checked / its bolts.','railing.s1 指由横杆构成的防护栏，常设于阳台、楼梯或桥边。','父亲检查阳台栏杆的螺栓。'),M('The child leaned over the balcony railing because it was a gap in the floor with no bars or protection.','The child leaned against the balcony railing, a protective barrier fixed along its edge.','railing 是边缘的防护栏，不是没有横杆的地面缺口。','meaning'),[q('Where did the child lean?','against the balcony railing','against the railway engine','on a rainwater tank','孩子靠着阳台栏杆。'),q('What did her father check?','whether every railing bolt was secure','whether the train had reached its railhead','whether the rainbow had faded','父亲检查了栏杆螺栓。',1,'context'),q('Where would a railing commonly be found?','along a staircase','inside a raindrop','under a radio broadcast','楼梯旁常安装栏杆。',1,'meaning'),q('What is railing formed from?','rail plus -ing','rain plus -y','rally plus -er','railing 由 rail 加 -ing 构成。',1,'word-formation')]);
P('railroad','Railroad combines rail and road; in North American English it names a railway track system or the company operating trains on it.',C('railroad.s1','铁路；铁路公司','The railroad added a freight branch to connect the grain depot with the port and reduce truck traffic.','铁路公司增建了一条货运支线，把谷物仓库与港口连接起来，以减少卡车运输。','The railroad added a freight branch / connecting the grain depot / with the port.','railroad.s1 指铁路轨道系统，也可指经营列车运输的公司。','铁路支线把仓库和港口连接起来。'),M('The railroad company moved the grain depot by replacing its train tracks with a line of balcony railings.','The railroad company built a new track branch so freight trains could reach the port.','铁路轨道供列车行驶，不是阳台上的栏杆。','meaning'),[q('What places did the railroad’s new branch connect?','the grain depot and the port','the balcony and the stairway','the mountain camp and the rain forest','铁路新支线连接了谷物仓库和港口。'),q('What can railroad name?','a train-track system or its operating company','only a handrail on stairs','a public meeting in support of a cause','railroad 可指铁路系统或铁路公司。',1,'meaning'),q('Which use is North American?','The railroad schedules freight trains.','The rainbow schedules freight trains.','The rainfall schedules freight trains.','railroad 可在北美英语中指铁路公司。',1,'grammar'),q('What two words form railroad?','rail and road','rain and road','rally and head','railroad 由 rail 与 road 组合而成。',1,'word-formation')]);
P('railway','Railway combines rail and way; it names train tracks and, by extension, the network or organization that operates trains.',[C('railway.s1','铁路；铁道','Workers replaced a cracked section of railway before the passenger train returned to the route.','客运列车恢复运行前，工人更换了一段开裂的铁轨。','Workers replaced a cracked railway section / before the passenger train / returned to the route.','railway.s1 指供列车行驶的铁道。','工人维修了开裂的铁路轨道。'),C('railway.s2','铁路系统；铁路公司','The national railway published a new timetable covering regional services and long-distance trains.','国家铁路公司发布了涵盖地区线路和长途列车的新时刻表。','The national railway published a timetable / covering regional and long-distance / services.','railway.s2 可指管理列车线路与服务的铁路系统或机构。','铁路机构公布了线路时刻表。')],M('The railway published a train timetable, but the word railway refers only to the handrail beside a staircase.','The railway published a train timetable for its network of tracks and passenger services.','railway 可指铁道或铁路运输系统，不限于楼梯扶手。','meaning'),[q('What did workers replace?','a cracked section of track','a broken balcony railing','a rainbow-colored raincoat','工人更换了一段开裂铁轨。',1,'context'),q('Who published the new timetable?','the national railway','the local rainfall office','the harbor railhead’s guard','国家铁路机构发布了新时刻表。',2,'context'),q('Which meaning is used in “the railway runs regional trains”?','the train network or operating organization','a handrail on a staircase','a narrow strip of falling rain','此处 railway 指铁路系统或运营机构。',2,'meaning'),q('How is railway formed?','rail plus way','rain plus fall','rake plus -ly','railway 由 rail 和 way 组合而成。',1,'word-formation')]);
P('rain','Rain comes from Old English regn, from a Germanic root; it can name falling water or a shower of things, and it can describe rain falling or things arriving in abundance.',[C('rain.s1','雨；雨水','Rain drummed on the greenhouse roof while the gardeners moved the seedlings away from the leaking corner.','雨水敲打着温室屋顶，园丁把幼苗移离漏水的角落。','Rain drummed on the roof / while gardeners moved seedlings / from the leak.','rain.s1 指从云中以水滴形式降落的水。','雨落在温室屋顶并造成漏水。'),C('rain.s2','一阵；大量落下的东西','A rain of confetti covered the players as they accepted the championship trophy.','球员们举起冠军奖杯时，彩纸如雨般落下。','A rain of confetti covered the players / as they accepted / the trophy.','rain.s2 可比喻大量事物连续落下或涌来。','彩纸大量飘落在球员身上。'),C('rain.s3','下雨','It rained throughout the night, so the outdoor rally moved into the station hall.','整夜都在下雨，因此户外集会改到了车站大厅。','It rained throughout the night / so the outdoor rally / moved indoors.','rain.s3 作动词表示雨水从天空降落。','整夜下雨使集会转移到室内。'),C('rain.s4','使大量落下；雨点般袭来','The crowd rained questions on the mayor after she announced the sudden closure of the railway.','市长宣布铁路突然关闭后，人群向她抛出连珠炮似的问题。','The crowd rained questions on the mayor / after the closure announcement.','rain.s4 作及物动词可表示使某物大量或密集地落下。','人群接连向市长提问。')],M('It rained all night, so the outdoor rally stayed completely dry under the open sky.','It rained all night, so the outdoor rally moved into a covered station hall.','整夜下雨时，在露天举行的集会不会完全保持干燥。','meaning'),[q('What did the gardeners move away from the leak?','the seedlings','the railroad timetable','the broken tennis racket','园丁把幼苗移离漏水处。',1,'context'),q('What covered the players after the final?','a rain of confetti','a raincoat','a line of railway sleepers','彩纸如雨般落在球员身上。',2,'context'),q('Why did the outdoor rally move indoors?','it rained throughout the night','a railhead had been closed','the crowd began to rake the field','整夜下雨使户外集会转入室内。',3,'context'),q('In “The crowd rained questions on the mayor,” what does rained mean?','sent many questions rapidly','waited for water to fall','walked slowly in the rain','这里 rained 表示大量、接连地提出问题。',4,'meaning')]);
P('rainbow','Rainbow combines rain and bow; it names the colored arc formed when sunlight shines through rain and can describe a varied mix.',[C('rainbow.s1','彩虹','A bright rainbow appeared above the valley when sunlight broke through the shower.','阳光穿过阵雨后，山谷上空出现了一道明亮的彩虹。','A rainbow appeared above the valley / when sunlight broke through / the shower.','rainbow.s1 指阳光经过雨滴折射后在天空形成的弧形彩带。','阵雨后阳光照出彩虹。'),C('rainbow.s2','多种颜色或群体的组合','The coalition formed a rainbow of neighborhood groups, including residents from every district and age range.','联盟汇集了各色社区团体，成员来自每个地区和各个年龄层。','The coalition formed a rainbow of groups / including residents / from every district.','rainbow.s2 可比喻多种颜色或不同类型人群组成的丰富组合。','联盟成员来自不同地区和年龄群体。')],M('The photographer called the clear blue sky a rainbow even though no arc or range of colors appeared.','The photographer called the colored arc above the valley a rainbow.','彩虹是天空中的彩色弧带，单一蓝色天空不符合该义。','meaning'),[q('What appeared when sunlight broke through the shower?','a bright rainbow','a railway head','a radium sample','阵雨后阳光照出了彩虹。',1,'context'),q('What made up the coalition’s rainbow of groups?','residents from every district and age range','only one group from one street','a collection of rain droplets','联盟由来自不同地区和年龄层的人组成。',2,'context'),q('What conditions commonly produce a rainbow?','sunlight shining through rain','a storm with no light or water','a radio signal bouncing from a rail','阳光穿过雨滴时常会出现彩虹。',1,'meaning'),q('Which phrase uses rainbow figuratively?','a rainbow of community groups','a rainbow above the valley after rain','a rainbow formed by sunlight and raindrops','rainbow of groups 比喻多样群体的组合。',1,'meaning')]);
P('raincoat','Raincoat combines rain and coat; it names outer clothing designed to keep rain from soaking the wearer.',[C('raincoat.s1','雨衣','She packed a lightweight raincoat because the forecast called for showers during the afternoon hike.','天气预报说下午徒步时会有阵雨，因此她带了一件轻便雨衣。','She packed a raincoat / because showers were forecast / during the hike.','raincoat.s1 指专为防雨而穿的外套。','她因预计有阵雨而带上雨衣。'),C('raincoat.s2','防雨外衣（泛指）','The cycling guide wore a thin waterproof raincoat over her jersey while leading the group in drizzle.','细雨中带队骑行时，向导在运动衫外面穿了一件薄防水外衣。','The guide wore a waterproof raincoat / over her jersey / in the drizzle.','raincoat.s2 可泛指布料不透雨的轻便外衣。','向导穿着防水外衣在细雨中骑行。')],M('She wore a raincoat with a large hole across the shoulders and expected it to keep every raindrop off her clothes.','She wore a waterproof raincoat with sealed seams to stay dry in the shower.','有大洞的外衣无法有效阻挡雨水。','meaning'),[q('Why did she pack a raincoat?','showers were forecast during the hike','the group expected a radiometric test','the trail ended at a railhead','她预计徒步时会遇到阵雨。'),q('What did the cycling guide wear over her jersey?','a thin waterproof raincoat','a wooden raft','a blanket of confetti','向导在运动衫外穿了防水外衣。',2,'context'),q('What is a raincoat designed to do?','keep rain from soaking the wearer','measure how much rain falls','turn sunlight into a rainbow','雨衣用于防止雨水浸湿穿着者。',1,'meaning'),q('Which words form raincoat?','rain and coat','rail and coat','rally and rain','raincoat 由 rain 和 coat 组合而成。',1,'word-formation')]);
P('raindrop','Raindrop combines rain and drop; it is one small body of water falling from a cloud as rain.',C('raindrop.s1','雨点','One raindrop landed on the microscope slide, so the researcher dried it before preparing the sample.','一滴雨落在显微镜载玻片上，研究人员便先把它擦干再制备样品。','One raindrop landed on the slide / so the researcher dried it / before preparing the sample.','raindrop.s1 指从云中落下的一小滴雨水。','研究人员擦掉了载玻片上的雨滴。'),M('A single raindrop covered the whole valley with a deep flood before anyone noticed it falling.','A single raindrop landed on the slide, while many drops together can contribute to flooding.','单个雨滴不会瞬间淹没整个山谷。','meaning'),[q('Where did the raindrop land?','on the microscope slide','on the railroad track','on the raccoon’s tennis racket','雨滴落在显微镜载玻片上。'),q('What did the researcher do next?','dried the slide before preparing a sample','used the drop to repair a radiator','measured the railhead’s length','研究人员擦干载玻片后才制备样品。',1,'context'),q('What is a raindrop?','one small body of water falling as rain','a large forest receiving heavy rainfall','a coat worn to stay dry','raindrop 指一滴雨水。',1,'meaning'),q('What does drop mean in raindrop?','a small amount of liquid','a railway company','an angry speech','此处 drop 指一小滴液体。',1,'word-formation')]);
P('rainer','Rainer is formed from rain and -er; in this technical sense it names equipment that sprinkles water over crops in a rain-like pattern.',C('rainer.s1','喷灌装置','The farm tested a rainer on the seed plot to distribute water evenly without flooding the young plants.','农场在播种地块试用喷灌装置，均匀供水而不淹没幼苗。','The farm tested a rainer / to distribute water evenly / over the seed plot.','rainer.s1 指模拟降雨、把水喷洒在农田或试验地上的设备。','喷灌装置均匀浇灌幼苗。'),M('The farmer called the rainer a dry storage shed because it sprinkled no water over the crop rows.','The farmer used the rainer to sprinkle water evenly over the crop rows.','rainer 在此指喷水灌溉设备，不是干燥仓库。','meaning'),[q('Where did the farm test the rainer?','on the seed plot','on the railway platform','inside the radio studio','农场在播种地块试用喷灌装置。'),q('What did the rainer distribute?','water evenly over young plants','radio messages to the harbor','confetti over the rally','装置把水均匀喷到幼苗上。',1,'context'),q('What is a rainer in this technical entry?','equipment that sprinkles water like rain','a person who repairs a raincoat','a forest that receives heavy rain','此处 rainer 是喷灌设备。',1,'meaning'),q('Which ending makes rainer the name of a device or agent?','-er','-ity','-less','rain 加 -er 构成 rainer。',1,'word-formation')]);
P('rainfall','Rainfall combines rain and fall; it means rain that falls in a place or the measured amount over a period.',C('rainfall.s1','降雨；降雨量','Annual rainfall in the basin fell below average, so officials asked residents to conserve water.','流域年降雨量低于平均水平，因此官员要求居民节约用水。','Annual rainfall fell below average / so officials asked residents / to conserve water.','rainfall.s1 可指降雨本身，也可指某地某段时间的降雨量。','降雨量偏少促使政府呼吁节水。'),M('The report said rainfall had risen because not a single drop of rain had fallen during the entire year.','The report said rainfall had risen after repeated storms brought heavy rain to the basin.','没有降雨不能说明降雨量增加；降雨量上升意味着降水更多。','meaning'),[q('What happened to annual rainfall in the basin?','it fell below average','it doubled after a single dry day','it became a railway company','流域年降雨量低于平均水平。'),q('What did officials ask residents to do?','conserve water','build a railhead','start a raffle','官员要求居民节约用水。',1,'context'),q('What does rainfall measure?','how much rain falls over a place and period','the number of raindrops in one cloud exactly','the length of a rainbow','rainfall 可表示某地某段时间的降雨量。',1,'meaning'),q('Which compound forms rainfall?','rain and fall','rain and rail','rally and fall','rainfall 由 rain 和 fall 构成。',1,'word-formation')]);
P('rainforest','Rainforest combines rain and forest; it names a dense forest that receives heavy rain during most of the year.',C('rainforest.s1','雨林','Researchers followed a marked trail through the rainforest and recorded birds heard in the high canopy.','研究人员沿标记小径穿过雨林，记录在高层树冠中听到的鸟类。','Researchers followed a trail / through the rainforest / and recorded canopy birds.','rainforest.s1 指大部分时间降雨充沛、植被茂密的森林。','研究人员在雨林中记录树冠鸟类。'),M('The guide called the dry treeless desert a rainforest even though it received almost no rain and had no dense forest.','The guide called the wet, densely wooded region a rainforest because it receives heavy rain through most of the year.','雨林需要降雨充沛且森林茂密，干旱无树的沙漠不符合定义。','meaning'),[q('What did researchers record in the rainforest?','birds heard in the high canopy','the number of railway sleepers','the price of a radiator','研究人员记录了树冠层中听到的鸟类。'),q('What kind of place is a rainforest?','a dense forest with heavy rain through most of the year','a dry open area without trees','a small water drop from one cloud','雨林通常降雨充沛且林木茂密。',1,'meaning'),q('Where did the team walk?','along a marked trail through the forest','along the railhead after snowfall','across a rainbow','研究人员沿着雨林中的标记小径行走。',1,'context'),q('Which words form rainforest?','rain and forest','rail and forest','rake and fall','rainforest 由 rain 与 forest 组成。',1,'word-formation')]);
P('rainwater','Rainwater combines rain and water; it can mean water falling as rain or rain collected and stored for later use.',[C('rainwater.s1','雨水（总称）','The roof channel directed rainwater into a garden bed, where it soaked the thirsty herbs.','屋顶水槽把雨水引到花坛里，滋润了缺水的香草。','The channel directed rainwater / into a garden bed / to soak the herbs.','rainwater.s1 泛指从云中落下的雨水。','屋顶将雨水引到花坛。'),C('rainwater.s2','收集贮存的雨水','The family stored rainwater in a covered tank and used it later to rinse tools and water non-edible plants.','这家人把雨水储存在有盖水箱中，之后用它冲洗工具、浇灌非食用植物。','The family stored rainwater / in a covered tank / for later garden use.','rainwater.s2 指收集并储存起来供以后使用的雨水。','家人储存雨水用于园艺。')],M('The family stored rainwater in an uncovered tank beside the road and assumed it could never collect dust or insects.','The family stored rainwater in a covered tank and filtered it before garden use.','储存雨水要防止污染，敞口水箱可能积灰或进虫。','context'),[q('Where did the roof channel direct rainwater?','into the garden bed','onto the railway timetable','into a radio speaker','屋顶水槽把雨水引进花坛。',1,'context'),q('What did the family store in a covered tank?','rainwater for later use','a rainbow for the next storm','a raft for the railhead','家人把雨水储存在有盖水箱中。',2,'context'),q('Which use best fits stored rainwater?','watering ornamental plants','drinking without treatment','cooling a car engine with radioactive liquid','储存雨水可用于浇灌非食用植物。',2,'meaning'),q('What is the difference between the two rainwater senses?','one is rain in general; the other is rain collected for later use','one means a storm; the other means a dry forest','one is a raincoat; the other is a raindrop','rainwater 可指一般雨水，也可特指收集储存的雨水。',1,'meaning')]);
P('rainy','Rainy is formed from rain and the adjective suffix -y; it means having much rain or frequent showers.',C('rainy.s1','下雨的；多雨的','They postponed the picnic because the forecast showed a rainy afternoon with showers continuing until dusk.','天气预报显示下午多雨、阵雨将持续到黄昏，因此他们推迟了野餐。','They postponed the picnic / because a rainy afternoon / was forecast.','rainy.s1 描述经常下雨或某段时间多雨。','预计下午有持续阵雨，野餐因此延期。'),M('The hikers called the day rainy even though the sky stayed cloudless and no water fell anywhere.','The hikers called the day rainy because showers kept falling over the trail.','rainy 描写有雨的天气，晴朗无雨不符合此义。','meaning'),[q('Why did the group postpone the picnic?','showers were forecast through the afternoon','the railway station had changed its name','a radio quiz had four questions','预计下午有阵雨，因此野餐延期。'),q('What is a rainy afternoon likely to have?','frequent showers','a perfectly cloudless sky','a dry forest fire','rainy 的下午很可能有阵雨。',1,'meaning'),q('Which sentence uses rainy naturally?','We wore boots on the rainy walk.','The radio was rainy with its volume turned down.','The radius became rainy after measurement.','rainy walk 指在雨天进行的散步。',1,'grammar'),q('Which suffix forms rainy from rain?','-y','-head','-er','rain 加形容词后缀 -y 构成 rainy。',1,'word-formation')]);
P('raise','Raise is related to Old Norse reisa, “to raise or lift”; it means move something upward or increase its level or amount.',C('raise.s1','举起；提高','The chair raised her hand to signal that she wanted to ask a question about the rainfall chart.','主席举手示意要就降雨量图表提问。','The chair raised her hand / to signal / a question about the chart.','raise.s1 指把物体或身体部位移到较高位置，也可指提高数值。','主席举手示意发言。'),M('The chair raised her hand by lowering it below the table where nobody could see it.','The chair raised her hand above the table so the speaker could see her request.','raise 表示向上移动；把手放低不能称为举起。','meaning'),[q('What did the chair raise?','her hand','the rainfall chart’s paper cover','the railway rail','主席举起了手。'),q('Why did she raise her hand?','to signal that she had a question','to keep the hand below the table','to make the rain stop','她举手示意要提问。',1,'context'),q('Which action means raise the water level?','add water to make it higher','remove water to make it lower','measure the tank without changing it','加水使水位升高就是 raise the level。',1,'meaning'),q('Which verb is a common opposite of raise?','lower','radiate','rally','lower 常与 raise 相对，表示降低。',1,'meaning')]);
P('rake','Rake is an Old English word for a toothed gardening tool; as a verb it means pull that tool over ground or search a place carefully.',C('rake.s1','耙；耙地；仔细搜寻','The gardener used a rake to gather wet leaves into a pile, then raked the soil smooth around the seedlings.','园丁用耙子把湿树叶拢成一堆，又把幼苗周围的土耙平。','The gardener used a rake / to gather leaves / and raked the soil smooth.','rake.s1 指带齿的园艺工具，也可作动词表示用耙整理地面或仔细搜寻。','园丁用耙清理树叶并整理土壤。'),M('The gardener raked the leaves by pushing them farther apart and scattering them across the clean path.','The gardener raked the leaves into a pile beside the path.','用耙收拢树叶应使它们聚在一起，而不是散得更开。','meaning'),[q('What did the gardener collect with the rake?','wet leaves','radio signals','rainwater in a sealed tank','园丁用耙收拢湿树叶。'),q('What did the gardener do to the soil?','raked it smooth around the seedlings','raided it for a radio receiver','raised it into a rainbow','园丁把幼苗周围的土耙平。',1,'context'),q('What is a rake?','a toothed gardening tool','a train track ending at a railhead','a device that measures radiation','rake 是带齿的园艺工具。',1,'meaning'),q('Which phrase uses rake as a verb meaning “search carefully”?','Police raked the warehouse for clues.','The rake leaned against the shed.','Rain fell on the garden rake.','raked the warehouse 表示仔细搜查仓库。',1,'grammar')]);
P('rally','Rally came through French rallier, “to bring together again”; it can be a public meeting, a recovery, a car race, or the acts of regrouping and recovering.',[C('rally.s1','公众集会；示威集会','Thousands attended a rally at the station square to support the campaign for safer railway crossings.','数千人参加了车站广场上的集会，支持改善铁路道口安全的行动。','Thousands attended a rally / at the station square / for safer crossings.','rally.s1 指为支持某项事业而举行的大型公众集会。','人们聚集起来支持铁路道口安全。'),C('rally.s2','回升；反弹','After several weeks of losses, the company’s shares staged a rally when its earnings exceeded forecasts.','连续数周下跌后，公司盈利超出预测，股价随即反弹。','The shares staged a rally / after earnings exceeded forecasts.','rally.s2 指价格、比分或健康状况下跌后恢复。','公司业绩超预期后股价回升。'),C('rally.s3','汽车拉力赛','The rally crossed gravel roads and mountain passes, with each car following a timed route.','拉力赛穿过碎石路和山口，每辆车都按计时路线行驶。','The rally crossed gravel roads / and mountain passes / on a timed route.','rally.s3 指汽车在公路或崎岖路段进行的长距离比赛。','汽车按计时路线通过山地路段。'),C('rally.s4','集合；重新集结','The rescue crews rallied at the railhead after the storm scattered them across the valley.','风暴把救援队伍分散到山谷各处后，他们在铁路终点重新集结。','The crews rallied at the railhead / after the storm / scattered them.','rally.s4 作动词表示分散的人重新聚集。','救援人员在铁路终点重新集合。'),C('rally.s5','恢复；回升','The patient rallied after surgery and was able to walk to the window the next morning.','手术后患者逐渐恢复，第二天早上已经能走到窗边。','The patient rallied after surgery / and walked / to the window the next morning.','rally.s5 作动词表示健康或力量从低迷状态恢复。','患者术后逐渐好转。')],M('The rally was a public meeting, but the report said the crowd rallied by scattering farther apart and refusing to regroup.','The crowd rallied by coming together again after the storm had scattered the rescue crews.','rally 作“重新集结”时表示再次聚在一起，而不是继续分散。','meaning'),[q('What cause did the station-square rally support?','safer railway crossings','a new raincoat design','the sale of radium paint','集会支持改善铁路道口安全。',1,'context'),q('What happened to the company’s shares after strong earnings?','they staged a rally','they turned into a car race','they fell below the railway tracks','公司股价在盈利超预期后反弹。',2,'context'),q('What kind of event crossed gravel roads and mountain passes?','a timed car rally','a public-health meeting','a rainbow display','汽车拉力赛穿过碎石路和山口。',3,'context'),q('What happened to the patient after surgery?','the patient recovered enough to walk','the patient joined a public meeting','the patient drove a timed mountain race','患者术后恢复到可以走路。',5,'context')]);
P('ramble','Ramble is a Middle English verb for wandering; its deeper origin is uncertain, and it can mean walk without a fixed route or speak at excessive length without clear direction.',[C('ramble.s1','漫步；闲逛','We rambled along the river path without choosing a destination and stopped whenever a bird appeared.','我们沿河边小路漫步，没有预定目的地，看到鸟儿就停下来。','We rambled along the path / without choosing a destination / and stopped to watch birds.','ramble.s1 指为了消遣而漫无固定路线地散步。','他们随意沿河漫步并观察鸟类。'),C('ramble.s2','漫谈；冗长讲述','The witness began to ramble about unrelated childhood memories, so the lawyer asked her to answer the question directly.','证人开始冗长地讲述无关的童年回忆，律师便请她直接回答问题。','The witness rambled about memories / unrelated to the case / until the lawyer redirected her.','ramble.s2 作动词表示讲话冗长、散乱而离题。','律师把证人从离题叙述中引回问题。')],M('The witness rambled in a concise, focused sentence that answered the lawyer’s question in five words.','The witness rambled through several unrelated stories before the lawyer redirected her.','简洁直接的回答不是冗长散乱的 ramble。','meaning'),[q('Where did the walkers ramble?','along the river path','through the radiological laboratory','around the railway timetable','他们沿河边小路漫步。',1,'context'),q('Why did the lawyer redirect the witness?','she rambled about unrelated memories','she had measured the rainfall correctly','she arrived at the railhead on time','证人离题讲了很多童年回忆。',2,'context'),q('What does ramble mean of a walk?','wander without a fixed route','race toward a finish line','stand behind a railing','ramble 作散步义指漫无固定路线地走。',1,'meaning'),q('What does ramble mean of speech?','talk at length in a confused or unfocused way','give one precise answer','read a short radio warning','ramble 作讲话义指冗长散乱地说。',2,'meaning')]);
P('ramp','Ramp came through French rampe from ramper, “to creep or climb”; it names an inclined path or roadway used to move between levels.',C('ramp.s1','坡道；斜坡通道','The library installed a ramp beside the front steps so wheelchair users could enter without assistance.','图书馆在正门台阶旁安装了坡道，使轮椅使用者可以自行进入。','The library installed a ramp / beside the front steps / for independent access.','ramp.s1 指连接不同高度、可供人或车辆上下的倾斜通道。','坡道让轮椅使用者无须他人协助即可进入。'),M('The library built a ramp as a vertical wall with no sloping path between the sidewalk and the entrance.','The library built a gently sloping ramp from the sidewalk to the entrance.','坡道必须是有倾斜度、连接不同高度的通道。','meaning'),[q('Why did the library install a ramp?','to let wheelchair users enter independently','to keep rainwater in a tank','to mark the end of the railway','图书馆安装坡道方便轮椅使用者独立进出。'),q('Where was the ramp built?','beside the front steps','inside the rainforest canopy','at the center of a rainbow','坡道建在正门台阶旁。',1,'context'),q('What is a ramp?','an inclined path between different levels','a vertical wall with no slope','a handrail fixed beside stairs','ramp 是连接不同高度的倾斜通道。',1,'meaning'),q('Which verb is behind the French source of ramp?','ramper, “to creep or climb”','rallier, “to reassemble”','radiare, “to shine”','ramp 经法语 rampe 与 ramper“攀爬”有关。',1,'word-formation')]);
P('rampage','Rampage is formed from ramp with -age; it names a sudden violent rush through a place, often causing damage.',C('rampage.s1','横冲直撞；暴走','The escaped bull went on a rampage through the market, overturning stalls before handlers guided it into an empty yard.','逃脱的公牛在市场里横冲直撞，掀翻摊位，直到驯养员把它引进空院子。','The bull went on a rampage / through the market / overturning stalls.','rampage.s1 指突然猛烈地冲闯某处，常伴随破坏。','公牛冲过市场并撞翻摊位。'),M('The bull went on a rampage by walking calmly through the market without touching a stall or frightening anyone.','The bull went on a rampage by charging through the market and overturning stalls.','平静行走且没有造成骚动，不符合 rampage 的猛烈失控含义。','meaning'),[q('What did the bull overturn during its rampage?','market stalls','a railway timetable','a rainwater tank','公牛冲过市场时撞翻了摊位。'),q('Who finally guided the bull into an empty yard?','its handlers','the radio announcers','the people at a raffle','驯养员把公牛引入空院子。',1,'context'),q('What does go on a rampage mean?','rush violently through a place and cause damage','walk quietly along a river path','climb a gentle access slope','go on a rampage 指横冲直撞并造成破坏。',1,'meaning'),q('Which ending helps form the noun rampage?','-age','-ly','-ness','ramp 加 -age 构成 rampage。',1,'word-formation')]);
})();
